  1→package vfs
  2→
  3→// optional.go —— **可选能力接口**。
  4→//
  5→// 为什么不直接加进 fs.go 的 Handle/FileSystem：那两个接口是跨模块契约
  6→// （AGENTS.md §7.3），每加一个方法所有实现都得跟着改。而这里的能力
  7→// 是「后端支持就用，不支持就退化」的性质，用可选接口 + 类型断言表达更合适：
  8→//
  9→//	if d, ok := handle.(vfs.DeleteOnCloser); ok {
 10→//	    err = d.SetDeleteOnClose(true)
 11→//	} else {
 12→//	    err = vfs.ErrNotSupported
 13→//	}
 14→//
 15→// 这也是 Go 标准库的惯用法（io.ReaderFrom / http.Flusher 都是这个套路）。
 16→
 17→import "os"
 18→
 19→// DeleteOnCloser 让已打开的句柄可以**事后**被标记为「关闭时删除」。
 20→//
 21→// 对应 SMB2 SET_INFO 的 FileDispositionInformation（MS-FSCC §2.4.11）：
 22→// 客户端删文件的标准流程是 CREATE(带 DELETE 权限) → SET_INFO(DeletePending=1)
 23→// → CLOSE，而不是发一个「删除」命令。CREATE 时的 FILE_DELETE_ON_CLOSE
 24→// 只是另一条路径。
 25→type DeleteOnCloser interface {
 26→	SetDeleteOnClose(del bool) error
 27→}
 28→
 29→// SparseFile 是稀疏文件能力。
 30→//
 31→// Time Machine 的 .sparsebundle 由大量固定大小的 band 文件组成，
 32→// 备份过期回收时会把 band 里的区间置零。没有打洞能力的话，
 33→// 备份卷只会越来越大、永远不会缩小（AGENTS.md §2 阶段二）。
 34→//
 35→// 对应 SMB2 IOCTL 的 FSCTL_SET_ZERO_DATA / FSCTL_SET_SPARSE。
 36→type SparseFile interface {
 37→	// PunchHole 把 [off, off+length) 释放成空洞，读回来是零。
 38→	// 文件逻辑长度不变。
 39→	PunchHole(off, length int64) error
 40→
 41→	// Preallocate 预留 [off, off+length) 的空间但不改变文件逻辑长度
 42→	// （对应 AllocationSize / AlSi create context）。
 43→	Preallocate(off, length int64) error
 44→}
 45→
 46→// AppleMetadata 一次性取出 AAPL readdir_attr 需要的 Apple 元数据。
 47→//
 48→// 为什么要有这个：macOS 的 AAPL create context 协商成功后，
 49→// QUERY_DIRECTORY 的每一条目录项都可以顺带携带资源派生大小与 FinderInfo
 50→// （Samba `source3/lib/readdir_attr.h` 的 `struct aapl`）。
 51→// 没有它，Finder 为了拿到同样的信息要对**每个文件**额外开两次流，
 52→// 在 Time Machine 的十万级 band 目录上是灾难性的往返次数。
 53→//
 54→// 由 FileSystem 实现，用类型断言取：
 55→//
 56→//	if am, ok := fs.(vfs.AppleMetadata); ok {
 57→//	    fi, rsrc, err := am.AppleInfo(name)
 58→//	}
 59→type AppleMetadata interface {
 60→	// AppleInfo 返回对象的 32 字节 FinderInfo 与资源派生大小。
 61→	//
 62→	// 对象存在但没有 Apple 元数据时返回全零 FinderInfo、大小 0 与 nil error
 63→	// ——「没有 FinderInfo」是正常状态，不是错误。
 64→	//
 65→	// 注意 wire 层拼 readdir_attr 时只用得到 FinderInfo 的一个**子集**
 66→	// （前 8 字节的类型/创建者码 + 偏移 8 起的标志位，且类型/创建者
 67→	// 仅对普通文件填充，目录留零 —— 见 vfs_fruit.c 的
 68→	// readdir_attr_meta_finderi）。这里返回完整 32 字节，切片由 wire 决定。
 69→	AppleInfo(path string) (finderInfo [FinderInfoSize]byte, rsrcSize int64, err error)
 70→}
 71→
 72→var (
 73→	_ DeleteOnCloser = (*localHandle)(nil)
 74→	_ SparseFile     = (*localHandle)(nil)
 75→	_ AppleMetadata  = (*LocalFS)(nil)
 76→)
 77→
 78→// AppleInfo 实现 AppleMetadata。
 79→func (l *LocalFS) AppleInfo(p string) ([FinderInfoSize]byte, int64, error) {
 80→	var fi [FinderInfoSize]byte
 81→
 82→	base, stream, err := SplitStreamPath(p)
 83→	if err != nil {
 84→		return fi, 0, err
 85→	}
 86→	if stream != "" {
 87→		// 对一个流查询 Apple 元数据是没有意义的请求。
 88→		return fi, 0, ErrInvalidPath
 89→	}
 90→	host, err := l.res.Resolve(base)
 91→	if err != nil {
 92→		return fi, 0, err
 93→	}
 94→	if _, err := os.Lstat(host); err != nil {
 95→		return fi, 0, mapError(err)
 96→	}
 97→
 98→	// 两者都是「没有就算了」：缺 FinderInfo 或缺资源派生都是正常状态。
 99→	if ai, err := l.readAfpInfo(host); err == nil {
100→		fi = ai.FinderInfo
101→	}
102→	rsrc, _ := resourceForkSize(dotUnderscoreName(host))
103→	return fi, rsrc, nil
104→}
105→
106→// SetDeleteOnClose 实现 DeleteOnCloser。
107→func (h *localHandle) SetDeleteOnClose(del bool) error {
108→	if h.fs.cfg.ReadOnly {
109→		return ErrReadOnly
110→	}
111→	h.mu.Lock()
112→	defer h.mu.Unlock()
113→	if h.closed {
114→		return ErrClosed
115→	}
116→	h.deleteOnClose = del
117→	return nil
118→}
119→
120→// PunchHole 实现 SparseFile。
121→func (h *localHandle) PunchHole(off, length int64) error {
122→	if err := checkRange(off, 0); err != nil || length < 0 {
123→		return ErrInvalidArg
124→	}
125→	if length > 0 && off > maxInt64-length {
126→		return ErrInvalidArg
127→	}
128→	if err := h.checkWritable(); err != nil {
129→		return err
130→	}
131→	if length == 0 {
132→		return nil
133→	}
134→	return platformPunchHole(h.f, off, length)
135→}
136→
137→// Preallocate 实现 SparseFile。
138→func (h *localHandle) Preallocate(off, length int64) error {
139→	if off < 0 || length < 0 || (length > 0 && off > maxInt64-length) {
140→		return ErrInvalidArg
141→	}
142→	if err := h.checkWritable(); err != nil {
143→		return err
144→	}
145→	if length == 0 {
146→		return nil
147→	}
148→	return platformPreallocate(h.f, off, length)
149→}
150→
151→const maxInt64 = int64(^uint64(0) >> 1)
152→

