  1→package vfs
  2→
  3→// local_handle.go —— Handle 接口的本地磁盘实现。
  4→//
  5→// 关键约束：
  6→//   - 所有来自网络的 offset/length 在使用前必须校验边界（AGENTS.md §8）。
  7→//     Go 的 pread/pwrite 对负 offset 会返回错误而不是崩，但**加法溢出**
  8→//     会把 off+len 绕回负数，必须自己拦。
  9→//   - 同一个句柄会被并发调用（客户端在一个 FileId 上并发下发 READ/WRITE），
 10→//     ReadAt/WriteAt 用 pread/pwrite 天然并发安全；有状态的只有目录枚举
 11→//     游标，用 mutex 保护。
 12→
 13→import (
 14→	"io"
 15→	"math"
 16→	"os"
 17→	"path/filepath"
 18→	"sort"
 19→	"sync"
 20→	"time"
 21→)
 22→
 23→type localHandle struct {
 24→	fs   *LocalFS
 25→	host string // 宿主机绝对路径
 26→	rel  string // 共享内相对路径（'/' 分隔）
 27→	name string // 末级名字，用于 HIDDEN 判定
 28→
 29→	// f 为 nil 表示 OpenAttrOnly 句柄：没有真正打开文件，只能查属性。
 30→	f *os.File
 31→
 32→	isDir        bool
 33→	writable     bool
 34→	writeThrough bool
 35→
 36→	mu            sync.Mutex
 37→	closed        bool
 38→	deleteOnClose bool
 39→
 40→	// 目录枚举状态。dirNames 是**一次性快照**：
 41→	// SMB2 的 QUERY_DIRECTORY 是分批拉取的，中途目录内容变化时
 42→	// 客户端期待看到的是一个稳定的视图（Windows 服务端亦然）。
 43→	dirNames []string
 44→	dirPos   int
 45→}
 46→
 47→var _ Handle = (*localHandle)(nil)
 48→
 49→// ---------------------------------------------------------------- 数据读写
 50→
 51→// checkRange 校验 offset/length。这是**防越界与整数溢出的唯一入口**。
 52→func checkRange(off int64, n int) error {
 53→	if off < 0 || n < 0 {
 54→		return ErrInvalidArg
 55→	}
 56→	if int64(n) > math.MaxInt64-off {
 57→		// off + n 会溢出成负数，后续任何比较都不可信。
 58→		return ErrInvalidArg
 59→	}
 60→	return nil
 61→}
 62→
 63→// ReadAt 实现 Handle。
 64→func (h *localHandle) ReadAt(p []byte, off int64) (int, error) {
 65→	if err := checkRange(off, len(p)); err != nil {
 66→		return 0, err
 67→	}
 68→	if h.isDir {
 69→		return 0, ErrIsDir
 70→	}
 71→	if h.f == nil {
 72→		// OpenAttrOnly 句柄没有数据流。
 73→		return 0, ErrNotSupported
 74→	}
 75→	n, err := h.f.ReadAt(p, off)
 76→	if err == io.EOF {
 77→		return n, io.EOF
 78→	}
 79→	return n, mapError(err)
 80→}
 81→
 82→// WriteAt 实现 Handle。
 83→func (h *localHandle) WriteAt(p []byte, off int64) (int, error) {
 84→	if err := checkRange(off, len(p)); err != nil {
 85→		return 0, err
 86→	}
 87→	if err := h.checkWritable(); err != nil {
 88→		return 0, err
 89→	}
 90→	n, err := h.f.WriteAt(p, off)
 91→	if err != nil {
 92→		return n, mapError(err)
 93→	}
 94→	if h.writeThrough {
 95→		// FILE_WRITE_THROUGH：客户端要求每次写都落盘。
 96→		// 慢，但这是它显式要的语义，不能偷懒。
 97→		if err := h.f.Sync(); err != nil {
 98→			return n, mapError(err)
 99→		}
100→	}
101→	return n, nil
102→}
103→
104→// checkWritable 收敛「这个句柄能不能写」的判断。
105→func (h *localHandle) checkWritable() error {
106→	if h.fs.cfg.ReadOnly {
107→		return ErrReadOnly
108→	}
109→	if h.isDir {
110→		return ErrIsDir
111→	}
112→	if h.f == nil {
113→		return ErrNotSupported
114→	}
115→	if !h.writable {
116→		// 句柄打开时没有申请写权限 → STATUS_ACCESS_DENIED。
117→		// SMB 的访问检查看的是 CREATE 时授予的权限，不是此刻的文件权限位。
118→		return ErrPermission
119→	}
120→	return nil
121→}
122→
123→// Truncate 实现 Handle（对应 FileEndOfFileInformation）。
124→func (h *localHandle) Truncate(size int64) error {
125→	if size < 0 {
126→		return ErrInvalidArg
127→	}
128→	if err := h.checkWritable(); err != nil {
129→		return err
130→	}
131→	return mapError(h.f.Truncate(size))
132→}
133→
134→// Sync 实现 Handle。
135→//
136→// full=true 对应 SMB2 FLUSH 与 macOS 的 F_FULLFSYNC：
137→// Time Machine 依赖它保证备份数据真的落到盘片上（AGENTS.md §2 阶段二）。
138→func (h *localHandle) Sync(full bool) error {
139→	if h.f == nil {
140→		return nil
141→	}
142→	if full {
143→		return mapError(platformFullSync(h.f))
144→	}
145→	return mapError(h.f.Sync())
146→}
147→
148→// ---------------------------------------------------------------- 属性
149→
150→// Stat 实现 Handle。
151→func (h *localHandle) Stat() (*Attr, error) {
152→	if h.f != nil {
153→		// 优先 fstat：句柄已经打开，即使文件被改名（甚至已被 unlink，
154→		// 例如 DELETE_ON_CLOSE 还没触发）也能拿到正确属性。
155→		if fi, err := h.f.Stat(); err == nil {
156→			a := attrFromFileInfo(fi, h.name, h.fs.cfg.ReadOnly)
157→			if bt, ok := statCreateTime(h.host); ok {
158→				a.CreateTime = bt
159→			}
160→			fillSysAttrFromFile(h.f, a)
161→			h.fs.applyMetadata(h.host, a)
162→			return a, nil
163→		}
164→	}
165→	return h.fs.statHost(h.host, h.name)
166→}
167→
168→// SetAttr 实现 Handle。
169→//
170→// 设计取舍：**无法表达的属性静默忽略，而不是报错**。
171→// Windows 在复制文件时会成套地设置 basic information，
172→// 其中的 CreateTime / ChangeTime / 大部分 DOS 位在 POSIX 上没有对应物；
173→// 若返回错误，Explorer 会认为整个复制失败。Samba 也是这么做的。
174→func (h *localHandle) SetAttr(attr *Attr, mask AttrMask) error {
175→	if attr == nil || mask == 0 {
176→		return nil
177→	}
178→	if h.fs.cfg.ReadOnly {
179→		return ErrReadOnly
180→	}
181→
182→	if mask&AttrSize != 0 {
183→		if err := h.Truncate(attr.Size); err != nil {
184→			return err
185→		}
186→	}
187→	if mask&AttrAlloc != 0 && h.f != nil && attr.Alloc > 0 {
188→		// 预分配失败不致命：它只是性能优化（AlSi create context）。
189→		_ = platformPreallocate(h.f, 0, attr.Alloc)
190→	}
191→
192→	if mask&(AttrAccessTime|AttrWriteTime) != 0 {
193→		var at, mt time.Time
194→		if mask&AttrAccessTime != 0 {
195→			at = attr.AccessTime
196→		}
197→		if mask&AttrWriteTime != 0 {
198→			mt = attr.WriteTime
199→		}
200→		if err := setTimes(h.host, at, mt); err != nil {
201→			return err
202→		}
203→	}
204→	if mask&AttrCreateTime != 0 && !attr.CreateTime.IsZero() {
205→		// POSIX 没有设置 btime 的接口；Windows 有（SetFileTime）。
206→		// 失败一律忽略，见函数头的说明。
207→		_ = platformSetCreateTime(h.f, h.host, attr.CreateTime)
208→	}
209→
210→	if mask&AttrFileAttributes != 0 {
211→		if err := h.setDOSAttributes(attr.FileAttributes); err != nil {
212→			return err
213→		}
214→	}
215→	if mask&AttrMode != 0 {
216→		if err := os.Chmod(h.host, os.FileMode(attr.Mode&0o7777)); err != nil {
217→			return mapError(err)
218→		}
219→	}
220→	if mask&(AttrUID|AttrGID) != 0 {
221→		h.setOwner(attr, mask)
222→	}
223→	return nil
224→}
225→
226→// setDOSAttributes 把 FILE_ATTRIBUTE_* 落到宿主机上。
227→//
228→// POSIX 上唯一有真实对应物的是 READONLY（写权限位）；
229→// HIDDEN/SYSTEM/ARCHIVE 等只能忽略。
230→// TODO: 阶段二可以像 Samba 那样存到 user.DOSATTRIB 扩展属性里，
231→// 那样 Windows 客户端设置的隐藏属性就能持久化。
232→func (h *localHandle) setDOSAttributes(attrs uint32) error {
233→	if err := platformSetDOSAttributes(h.host, attrs); err == nil {
234→		return nil
235→	} else if err != ErrNotSupported {
236→		return err
237→	}
238→
239→	fi, err := os.Stat(h.host)
240→	if err != nil {
241→		return mapError(err)
242→	}
243→	perm := fi.Mode().Perm()
244→	if attrs&FileAttributeReadonly != 0 {
245→		perm &^= 0o222
246→	} else {
247→		// 取消只读：恢复属主写位。不去猜组/其他人的写位，
248→		// 保守只加 u+w，避免把文件放宽给别人。
249→		perm |= 0o200
250→	}
251→	if perm == fi.Mode().Perm() {
252→		return nil
253→	}
254→	return mapError(os.Chmod(h.host, perm))
255→}
256→
257→// setOwner 记录属主。
258→//
259→// 注意 AGENTS.md §1.1：这里的 uid/gid 只是数字标签，**不做系统用户解析**，
260→// 也不调用 chown —— 真去 chown 需要 root，且会把本软件的账户体系和
261→// 宿主机的账户体系绑在一起，正是准则明令禁止的。
262→// 表达不了 POSIX 属主的平台（Windows）写进旁路存储，其余平台忽略。
263→func (h *localHandle) setOwner(attr *Attr, mask AttrMask) {
264→	if h.fs.meta == nil {
265→		return
266→	}
267→	rel, err := filepath.Rel(h.fs.res.Root(), h.host)
268→	if err != nil {
269→		return
270→	}
271→	key := filepath.ToSlash(rel)
272→	md, _ := h.fs.meta.Get(key)
273→	if mask&AttrUID != 0 {
274→		md.UID = attr.UID
275→	}
276→	if mask&AttrGID != 0 {
277→		md.GID = attr.GID
278→	}
279→	if mask&AttrMode != 0 {
280→		md.Mode = attr.Mode
281→	}
282→	_ = h.fs.meta.Put(key, md)
283→}
284→
285→// ---------------------------------------------------------------- 目录枚举
286→
287→// ReadDir 实现 Handle。
288→func (h *localHandle) ReadDir(pattern string, restart bool, max int) ([]DirEntry, error) {
289→	if !h.isDir {
290→		return nil, ErrNotDir
291→	}
292→	h.mu.Lock()
293→	defer h.mu.Unlock()
294→	if h.closed {
295→		return nil, ErrClosed
296→	}
297→
298→	if h.dirNames == nil || restart {
299→		if err := h.snapshotLocked(); err != nil {
300→			return nil, err
301→		}
302→	}
303→
304→	out := make([]DirEntry, 0, 64)
305→	for h.dirPos < len(h.dirNames) {
306→		if max > 0 && len(out) >= max {
307→			break
308→		}
309→		name := h.dirNames[h.dirPos]
310→		h.dirPos++
311→
312→		if !MatchDOS(pattern, name) {
313→			continue
314→		}
315→		a, err := h.entryAttr(name)
316→		if err != nil {
317→			// 条目在快照之后被删掉了 —— 跳过而不是让整批枚举失败。
318→			continue
319→		}
320→		out = append(out, DirEntry{Name: name, Attr: *a})
321→	}
322→
323→	if len(out) == 0 && h.dirPos >= len(h.dirNames) {
324→		// 枚举完毕。server 层据此回 STATUS_NO_MORE_FILES；
325→		// 若这是**第一次**调用就没有任何匹配，则应回 STATUS_NO_SUCH_FILE
326→		// （docs/protocol-notes.md §9），那个区分由 server 层做。
327→		return nil, io.EOF
328→	}
329→	return out, nil
330→}
331→
332→// snapshotLocked 拍一张目录内容的快照。
333→//
334→// 只读名字不读属性：Time Machine 的 band 目录可以有十万级条目，
335→// 一次性 lstat 全部会让首个 QUERY_DIRECTORY 卡住好几秒。
336→// 属性在每一批实际返回时才逐条取。
337→func (h *localHandle) snapshotLocked() error {
338→	f, err := os.Open(h.host)
339→	if err != nil {
340→		return mapError(err)
341→	}
342→	defer f.Close()
343→
344→	names, err := f.Readdirnames(-1)
345→	if err != nil {
346→		return mapError(err)
347→	}
348→	// 固定顺序：宿主机返回的顺序（ext4 的 htree）是哈希序，
349→	// 同一目录两次枚举可能不一致，客户端做增量对比时会困惑。
350→	sort.Strings(names)
351→
352→	// 过滤掉 SMB 表达不了的名字（含非法字符、Windows 保留设备名等）。
353→	// 它们即使列出来客户端也打不开（ValidateComponent 会拒），
354→	// 不如不列，免得出现「看得见摸不着」的条目。
355→	kept := make([]string, 0, len(names)+2)
356→	// Windows 期待枚举结果里带 "." 与 ".."（docs/protocol-notes.md §9）。
357→	kept = append(kept, ".", "..")
358→	for _, n := range names {
359→		if ValidateComponent(n) != nil {
360→			continue
361→		}
362→		// AppleDouble 资源派生旁路文件不作为独立条目出现：
363→		// 客户端要拿资源派生是通过 AFP_Resource 流，不是通过 ._foo。
364→		// 列出来会让 Finder 显示重影，也会让 Time Machine 的 band 计数翻倍。
365→		if isDotUnderscoreName(n) {
366→			continue
367→		}
368→		kept = append(kept, n)
369→	}
370→
371→	h.dirNames = kept
372→	h.dirPos = 0
373→	return nil
374→}
375→
376→// entryAttr 取单条目录项的属性。
377→func (h *localHandle) entryAttr(name string) (*Attr, error) {
378→	switch name {
379→	case ".":
380→		return h.fs.statHost(h.host, ".")
381→	case "..":
382→		parent := filepath.Dir(h.host)
383→		// 共享根的 ".." 指向自己：绝不能让客户端顺着它走到共享外。
384→		if h.host == h.fs.res.Root() || !h.fs.res.contains(parent) {
385→			parent = h.fs.res.Root()
386→		}
387→		return h.fs.statHost(parent, "..")
388→	default:
389→		return h.fs.statHost(filepath.Join(h.host, name), name)
390→	}
391→}
392→
393→// ---------------------------------------------------------------- 其他
394→
395→// Xattr 实现 Handle。
396→func (h *localHandle) Xattr() (XattrAccessor, error) {
397→	return newXattrAccessor(h.host, h.f)
398→}
399→
400→// Close 实现 Handle。
401→func (h *localHandle) Close() error {
402→	h.mu.Lock()
403→	if h.closed {
404→		h.mu.Unlock()
405→		return nil
406→	}
407→	h.closed = true
408→	del := h.deleteOnClose
409→	f := h.f
410→	h.f = nil
411→	h.dirNames = nil
412→	h.mu.Unlock()
413→
414→	var firstErr error
415→	if f != nil {
416→		if err := f.Close(); err != nil {
417→			firstErr = mapError(err)
418→		}
419→	}
420→	if del && !h.fs.cfg.ReadOnly {
421→		// 先 close 再 unlink：Windows 上打开中的文件默认删不掉
422→		// （Go 的 os.OpenFile 不带 FILE_SHARE_DELETE），
423→		// 这个顺序在三个平台上都成立。
424→		if err := os.Remove(h.host); err != nil && !os.IsNotExist(err) && firstErr == nil {
425→			firstErr = mapError(err)
426→		} else if err == nil {
427→			h.fs.forgetMetadata(h.host)
428→		}
429→	}
430→	return firstErr
431→}
