  3→// local_handle.go —— Handle 接口的本地磁盘实现。
  4→//
  5→// 关键约束：
  6→//   - 所有来自网络的 offset/length 在使用前必须校验边界（AGENTS.md §8）。
  7→//     Go 的 pread/pwrite 对负 offset 会返回错误而不是崩，但**加法溢出**
  8→//     会把 off+len 绕回负数，必须自己拦。
  9→//   - 同一个句柄会被并发调用（客户端在一个 FileId 上并发下发 READ/WRITE），
 10→//     ReadAt/WriteAt 用 pread/pwrite 天然并发安全；有状态的只有目录枚举
 11→//     游标，用 mutex 保护。
 12→
 13→import (
 14→	"io"
 15→	"math"
 16→	"os"
 17→	"path/filepath"
 18→	"sort"
 19→	"sync"
 20→	"time"
 21→)
 22→
 23→type localHandle struct {
 24→	fs   *LocalFS
 25→	host string // 宿主机绝对路径
 26→	rel  string // 共享内相对路径（'/' 分隔）
 27→	name string // 末级名字，用于 HIDDEN 判定
 28→
 29→	// f 为 nil 表示 OpenAttrOnly 句柄：没有真正打开文件，只能查属性。
 30→	f *os.File
 31→
 32→	isDir        bool
 33→	writable     bool
 34→	writeThrough bool
 35→
 36→	mu            sync.Mutex
 37→	closed        bool
 38→	deleteOnClose bool
 39→
 40→	// 目录枚举状态。dirNames 是**一次性快照**：
 41→	// SMB2 的 QUERY_DIRECTORY 是分批拉取的，中途目录内容变化时
 42→	// 客户端期待看到的是一个稳定的视图（Windows 服务端亦然）。
 43→	dirNames []string
 44→	dirPos   int
 45→}
 46→
 47→var _ Handle = (*localHandle)(nil)
 48→
 49→// ---------------------------------------------------------------- 数据读写
 50→
 51→// checkRange 校验 offset/length。这是**防越界与整数溢出的唯一入口**。
 52→func checkRange(off int64, n int) error {
 53→	if off < 0 || n < 0 {
 54→		return ErrInvalidArg
 55→	}
 56→	if int64(n) > math.MaxInt64-off {
 57→		// off + n 会溢出成负数，后续任何比较都不可信。
 58→		return ErrInvalidArg
 59→	}
 60→	return nil
 61→}
 62→
 63→// ReadAt 实现 Handle。
 64→func (h *localHandle) ReadAt(p []byte, off int64) (int, error) {
 65→	if err := checkRange(off, len(p)); err != nil {
 66→		return 0, err
 67→	}
 68→	if h.isDir {
 69→		return 0, ErrIsDir
 70→	}
 71→	if h.f == nil {
 72→		// OpenAttrOnly 句柄没有数据流。
 73→		return 0, ErrNotSupported
 74→	}
 75→	n, err := h.f.ReadAt(p, off)
 76→	if err == io.EOF {
 77→		return n, io.EOF
 78→	}
 79→	return n, mapError(err)
 80→}
 81→
 82→// WriteAt 实现 Handle。
 83→func (h *localHandle) WriteAt(p []byte, off int64) (int, error) {
 84→	if err := checkRange(off, len(p)); err != nil {
 85→		return 0, err
 86→	}
 87→	if err := h.checkWritable(); err != nil {
 88→		return 0, err
 89→	}
 90→	n, err := h.f.WriteAt(p, off)
 91→	if err != nil {
 92→		return n, mapError(err)
 93→	}
 94→	if h.writeThrough {
 95→		// FILE_WRITE_THROUGH：客户端要求每次写都落盘。
 96→		// 慢，但这是它显式要的语义，不能偷懒。
 97→		if err := h.f.Sync(); err != nil {
 98→			return n, mapError(err)
 99→		}
100→	}
101→	return n, nil
102→}
103→
104→// checkWritable 收敛「这个句柄能不能写」的判断。
105→func (h *localHandle) checkWritable() error {
106→	if h.fs.cfg.ReadOnly {
107→		return ErrReadOnly
108→	}
109→	if h.isDir {
110→		return ErrIsDir
111→	}
112→	if h.f == nil {
113→		return ErrNotSupported
114→	}
115→	if !h.writable {
116→		// 句柄打开时没有申请写权限 → STATUS_ACCESS_DENIED。
117→		// SMB 的访问检查看的是 CREATE 时授予的权限，不是此刻的文件权限位。
118→		return ErrPermission
119→	}
120→	return nil
121→}
122→
123→// Truncate 实现 Handle（对应 FileEndOfFileInformation）。
124→func (h *localHandle) Truncate(size int64) error {
125→	if size < 0 {
126→		return ErrInvalidArg
127→	}
128→	if err := h.checkWritable(); err != nil {
129→		return err
130→	}
131→	return mapError(h.f.Truncate(size))
132→}
133→
134→// Sync 实现 Handle。
135→//
136→// full=true 对应 SMB2 FLUSH 与 macOS 的 F_FULLFSYNC：
137→// Time Machine 依赖它保证备份数据真的落到盘片上（AGENTS.md §2 阶段二）。
138→func (h *localHandle) Sync(full bool) error {
139→	if h.f == nil {
140→		return nil
141→	}
142→	if full {
143→		return mapError(platformFullSync(h.f))
144→	}
145→	return mapError(h.f.Sync())
146→}
