152→	if h.f != nil {
153→		// 优先 fstat：句柄已经打开，即使文件被改名（甚至已被 unlink，
154→		// 例如 DELETE_ON_CLOSE 还没触发）也能拿到正确属性。
155→		if fi, err := h.f.Stat(); err == nil {
156→			a := attrFromFileInfo(fi, h.name, h.fs.cfg.ReadOnly)
157→			if bt, ok := statCreateTime(h.host); ok {
158→				a.CreateTime = bt
159→			}
