346→		return mapError(err)
347→	}
348→	// 固定顺序：宿主机返回的顺序（ext4 的 htree）是哈希序，
349→	// 同一目录两次枚举可能不一致，客户端做增量对比时会困惑。
350→	sort.Strings(names)
351→
352→	// 过滤掉 SMB 表达不了的名字（含非法字符、Windows 保留设备名等）。
353→	// 它们即使列出来客户端也打不开（ValidateComponent 会拒），
354→	// 不如不列，免得出现「看得见摸不着」的条目。
355→	kept := make([]string, 0, len(names)+2)
356→	// Windows 期待枚举结果里带 "." 与 ".."（docs/protocol-notes.md §9）。
357→	kept = append(kept, ".", "..")
358→	for _, n := range names {
359→		if ValidateComponent(n) != nil {
360→			continue
361→		}
362→		// AppleDouble 资源派生旁路文件不作为独立条目出现：
363→		// 客户端要拿资源派生是通过 AFP_Resource 流，不是通过 ._foo。
364→		// 列出来会让 Finder 显示重影，也会让 Time Machine 的 band 计数翻倍。
365→		if isDotUnderscoreName(n) {
366→			continue
367→		}
368→		kept = append(kept, n)
369→	}
370→
371→	h.dirNames = kept
372→	h.dirPos = 0
373→	return nil
374→}
375→
376→// entryAttr 取单条目录项的属性。
377→func (h *localHandle) entryAttr(name string) (*Attr, error) {
378→	switch name {
379→	case ".":
380→		return h.fs.statHost(h.host, ".")
381→	case "..":
382→		parent := filepath.Dir(h.host)
383→		// 共享根的 ".." 指向自己：绝不能让客户端顺着它走到共享外。
384→		if h.host == h.fs.res.Root() || !h.fs.res.contains(parent) {
385→			parent = h.fs.res.Root()
386→		}
387→		return h.fs.statHost(parent, "..")
388→	default:
389→		return h.fs.statHost(filepath.Join(h.host, name), name)
390→	}
391→}
392→
393→// ---------------------------------------------------------------- 其他
394→
395→// Xattr 实现 Handle。
396→func (h *localHandle) Xattr() (XattrAccessor, error) {
397→	return newXattrAccessor(h.host, h.f)
398→}
399→
400→// Close 实现 Handle。
401→func (h *localHandle) Close() error {
402→	h.mu.Lock()
403→	if h.closed {
404→		h.mu.Unlock()
405→		return nil
406→	}
407→	h.closed = true
408→	del := h.deleteOnClose
409→	f := h.f
410→	h.f = nil
411→	h.dirNames = nil
412→	h.mu.Unlock()
413→
414→	var firstErr error
415→	if f != nil {
416→		if err := f.Close(); err != nil {
417→			firstErr = mapError(err)
418→		}
419→	}
420→	if del && !h.fs.cfg.ReadOnly {
421→		// 先 close 再 unlink：Windows 上打开中的文件默认删不掉
422→		// （Go 的 os.OpenFile 不带 FILE_SHARE_DELETE），
423→		// 这个顺序在三个平台上都成立。
424→		if err := os.Remove(h.host); err != nil && !os.IsNotExist(err) && firstErr == nil {
425→			firstErr = mapError(err)
426→		} else if err == nil {
427→			h.fs.forgetMetadata(h.host)
428→		}
429→	}
430→	return firstErr
431→}
