 68→// LocalFS 把宿主机的一个目录导出为 SMB 共享。
 69→//
 70→// 并发安全：所有方法可被多 goroutine 并发调用。
 71→type LocalFS struct {
 72→	res *Resolver
 73→	cfg LocalConfig
 74→
 75→	label  string
 76→	serial uint32
 77→
 78→	// meta 是 POSIX 属主/权限的旁路存储，只在宿主文件系统表达不了它们的
 79→	// 平台（Windows）上非 nil。Linux/macOS 上恒为 nil，零开销。
 80→	meta MetadataStore
 81→
 82→	closeOnce sync.Once
 83→}
