 85→// 编译期断言：LocalFS 必须满足 FileSystem 契约。
 86→var _ FileSystem = (*LocalFS)(nil)
 87→
 88→// NewLocalFS 构造一个本地磁盘共享。
 89→func NewLocalFS(cfg LocalConfig) (*LocalFS, error) {
 90→	res, err := NewResolver(cfg.Root, cfg.CaseInsensitive)
 91→	if err != nil {
 92→		return nil, err
 93→	}
 94→	if cfg.FileMode == 0 {
 95→		cfg.FileMode = defaultFileMode
 96→	}
 97→	if cfg.DirMode == 0 {
 98→		cfg.DirMode = defaultDirMode
 99→	}
100→
101→	label := cfg.VolumeLabel
102→	if label == "" {
103→		label = filepath.Base(res.Root())
104→	}
105→
106→	l := &LocalFS{
107→		res:    res,
108→		cfg:    cfg,
109→		label:  label,
110→		serial: volumeSerial(res.Root()),
111→	}
112→
113→	meta, err := openMetadataStore(res.Root(), cfg.MetadataPath)
114→	if err != nil {
115→		return nil, err
116→	}
117→	l.meta = meta
118→	return l, nil
119→}
120→
121→// volumeSerial 由共享根路径派生一个稳定的卷序列号。
122→//
123→// 为什么要稳定：Windows 客户端会缓存 (VolumeSerial, FileID) 作为文件身份，
124→// 服务重启后序列号变了会导致客户端缓存失效甚至误判文件被替换。
125→// 用路径哈希而不是随机数正是为了跨重启稳定。
126→func volumeSerial(root string) uint32 {
127→	h := fnv.New32a()
128→	_, _ = h.Write([]byte(root))
129→	s := h.Sum32()
130→	if s == 0 {
131→		s = 1 // 0 在部分客户端里被当作「无效卷」
132→	}
133→	return s
134→}
135→
136→// Root 返回共享根的宿主机绝对路径（供测试与日志用）。
137→func (l *LocalFS) Root() string { return l.res.Root() }
138→
139→// ReadOnly 实现 FileSystem。
140→func (l *LocalFS) ReadOnly() bool { return l.cfg.ReadOnly }
141→
142→// Close 实现 FileSystem。
143→func (l *LocalFS) Close() error {
144→	var err error
145→	l.closeOnce.Do(func() {
146→		if l.meta != nil {
147→			err = l.meta.Close()
148→		}
149→	})
150→	return err
151→}
152→
153→// ---------------------------------------------------------------- Open
154→
155→// Open 实现 FileSystem，把 SMB2 CREATE 的语义落到 os.OpenFile 上。
156→func (l *LocalFS) Open(req *OpenRequest) (Handle, Action, error) {
157→	if req == nil {
158→		return nil, 0, ErrInvalidArg
159→	}
160→	if l.cfg.ReadOnly && dispositionWrites(req.Disposition, req.Flags) {
161→		return nil, 0, ErrReadOnly
162→	}
163→
164→	// 流名有两个来源：显式的 req.Stream，以及路径里的 "file:stream:$DATA"
165→	// 语法。后者是 macOS 客户端常用的写法，必须在 Resolve **之前**剥掉，
166→	// 否则冒号会被当成非法文件名字符而拒绝掉一个合法请求。
167→	reqPath, stream := req.Path, req.Stream
168→	if stream == "" {
169→		var err error
170→		if reqPath, stream, err = SplitStreamPath(req.Path); err != nil {
171→			return nil, 0, err
172→		}
173→	} else if err := ValidateStreamName(stream); err != nil {
174→		return nil, 0, err
175→	}
176→
177→	host, err := l.res.Resolve(reqPath)
178→	if err != nil {
179→		return nil, 0, err
180→	}
181→	name := path.Base("/" + reqPath) // 根目录时得到 "/"，下面会归一
182→	if reqPath == "" {
183→		name = "."
184→	}
185→
186→	if stream != "" {
187→		return l.openStream(req, host, name, stream)
188→	}
189→
190→	fi, statErr := os.Lstat(host)
191→	exists := statErr == nil
192→	if statErr != nil && !os.IsNotExist(statErr) {
193→		return nil, 0, mapError(statErr)
194→	}
195→
196→	// 软链：Resolve 已确认其目标在共享内，这里求值成实路径，
197→	// 以便后面带 O_NOFOLLOW 打开时不会被 ELOOP 挡住（见 EvalFinal 的说明）。
198→	if exists && fi.Mode()&fs.ModeSymlink != 0 && req.Flags&OpenNoFollow == 0 {
199→		real, err := l.res.EvalFinal(host)
200→		if err != nil {
201→			return nil, 0, err
202→		}
203→		host = real
204→		if fi, err = os.Lstat(host); err != nil {
205→			return nil, 0, mapError(err)
206→		}
207→	}
208→
209→	isDir := exists && fi.IsDir()
210→	wantDir := req.Flags&OpenDirectory != 0
211→
212→	switch {
213→	case exists && isDir && req.Flags&OpenNonDirectory != 0:
214→		// FILE_NON_DIRECTORY_FILE 遇到目录 → STATUS_FILE_IS_A_DIRECTORY
215→		return nil, 0, ErrIsDir
216→	case exists && !isDir && wantDir:
217→		// FILE_DIRECTORY_FILE 遇到文件 → STATUS_NOT_A_DIRECTORY
218→		return nil, 0, ErrNotDir
219→	}
220→
221→	if isDir || (!exists && wantDir) {
222→		return l.openDir(req, host, name, exists)
223→	}
224→	return l.openFile(req, host, name, exists)
225→}
226→
227→// dispositionWrites 判断这次 CREATE 是否带有写意图。
228→// 只读共享在入口就要挡掉，不能等到真正写的时候才失败 ——
229→// 客户端拿到句柄之后会认为写一定成功。
230→func dispositionWrites(d Disposition, f OpenFlags) bool {
231→	if f&(OpenWrite|OpenAppend|OpenDeleteOnClose) != 0 {
232→		return true
233→	}
234→	switch d {
235→	case Supersede, CreateNew, OpenAlways, TruncateExisting, TruncateAlways:
236→		return true
237→	}
238→	return false
239→}
240→
241→// openDir 处理目录的打开与创建。
242→func (l *LocalFS) openDir(req *OpenRequest, host, name string, exists bool) (Handle, Action, error) {
243→	action := ActionOpened
244→
245→	if !exists {
246→		switch req.Disposition {
247→		case CreateNew, OpenAlways, TruncateAlways, Supersede:
248→			if err := os.Mkdir(host, l.cfg.DirMode); err != nil {
249→				return nil, 0, mapError(err)
250→			}
251→			action = ActionCreated
252→		default: // OpenExisting / TruncateExisting
253→			return nil, 0, ErrNotFound
254→		}
255→	} else {
256→		switch req.Disposition {
257→		case CreateNew:
258→			return nil, 0, ErrExist
259→		case Supersede, TruncateExisting, TruncateAlways:
260→			// 目录无法被截断/取代。Windows 在这里返回
261→			// STATUS_INVALID_PARAMETER，我们用 ErrIsDir 表达「对象是目录」。
262→			return nil, 0, ErrIsDir
263→		}
264→	}
265→
266→	h := l.newHandle(req, host, name, true)
267→	if req.Flags&OpenAttrOnly != 0 {
268→		return h, action, nil
269→	}
270→	// 目录只需读句柄：SMB 对目录的「写」是 SET_INFO（改属性/改名），
271→	// 那些操作走路径而不是 fd。
272→	f, err := os.OpenFile(host, os.O_RDONLY|openNoFollow, 0)
273→	if err != nil {
274→		return nil, 0, mapError(err)
275→	}
276→	h.f = f
277→	return h, action, nil
278→}
279→
280→// openFile 处理普通文件的打开与创建，实现 MS-SMB2 §2.2.13 的
281→// CreateDisposition 语义（对照表见 docs/protocol-notes.md §8）。
282→func (l *LocalFS) openFile(req *OpenRequest, host, name string, exists bool) (Handle, Action, error) {
283→	var (
284→		flag   int
285→		action Action
286→	)
287→	switch req.Disposition {
288→	case Supersede:
289→		// 「删除重建」：语义上原文件的属性、ADS 都应被丢弃。
290→		// 用 O_TRUNC 近似（内容清空、inode 保留）。
291→		// TODO: 严格实现需 unlink + create，但那会破坏其他已打开句柄，
292→		//       且 Windows 客户端极少用 SUPERSEDE，先按 Samba 的做法来。
293→		flag = os.O_CREATE | os.O_TRUNC
294→		if exists {
295→			action = ActionSuperseded
296→		} else {
297→			action = ActionCreated
298→		}
299→	case OpenExisting:
300→		if !exists {
301→			return nil, 0, ErrNotFound
302→		}
303→		action = ActionOpened
304→	case CreateNew:
305→		// O_EXCL 让「存在则失败」是原子的，不依赖上面的 lstat 结果。
306→		flag = os.O_CREATE | os.O_EXCL
307→		action = ActionCreated
308→	case OpenAlways:
309→		flag = os.O_CREATE
310→		if exists {
311→			action = ActionOpened
312→		} else {
313→			action = ActionCreated
314→		}
315→	case TruncateExisting:
316→		if !exists {
317→			return nil, 0, ErrNotFound
318→		}
319→		flag = os.O_TRUNC
320→		action = ActionOverwritten
321→	case TruncateAlways:
322→		flag = os.O_CREATE | os.O_TRUNC
323→		if exists {
324→			action = ActionOverwritten
325→		} else {
326→			action = ActionCreated
327→		}
328→	default:
329→		return nil, 0, ErrInvalidArg
330→	}
331→
332→	h := l.newHandle(req, host, name, false)
333→
334→	// 仅查属性：不真的 open。Explorer 会对目录里每个文件做一次属性探测，
335→	// 省下这一次 open/close 对大目录的收益很大（docs/protocol-notes.md §8）。
336→	// 注意此时若文件不存在且 disposition 要求创建，仍需真的创建出来。
337→	if req.Flags&OpenAttrOnly != 0 && flag&os.O_CREATE == 0 && flag&os.O_TRUNC == 0 {
338→		return h, action, nil
339→	}
340→
341→	f, err := os.OpenFile(host, flag|accessFlags(req.Flags, flag)|openNoFollow, l.cfg.FileMode)
342→	if err != nil {
343→		return nil, 0, mapError(err)
344→	}
345→	h.f = f
346→	return h, action, nil
347→}
348→
349→// accessFlags 把 OpenFlags 的读写意图翻译成 O_RDONLY/O_WRONLY/O_RDWR。
350→//
351→// 两点特别说明：
352→//
353→//  1. **绝不设置 O_APPEND**。SMB2 WRITE 永远带显式 offset（pwrite 语义），
354→//     O_APPEND 会让内核忽略 offset 把数据全追加到尾部，导致文件内容错乱。
355→//     协议里的「追加」是客户端发 offset=0xFFFFFFFFFFFFFFFF，
356→//     由 server 层换算成当前 EOF，不需要内核帮忙。
357→//  2. 若 disposition 要求 O_TRUNC/O_CREATE，即使客户端只请求了读权限，
358→//     也必须至少有写权限，否则 open 会 EACCES。
359→func accessFlags(f OpenFlags, dispFlag int) int {
360→	wantWrite := f&(OpenWrite|OpenAppend) != 0 || dispFlag&(os.O_TRUNC|os.O_CREATE) != 0
361→	wantRead := f&OpenRead != 0 || !wantWrite
362→
363→	switch {
364→	case wantRead && wantWrite:
365→		return os.O_RDWR
366→	case wantWrite:
367→		return os.O_WRONLY
368→	default:
369→		return os.O_RDONLY
370→	}
371→}
372→
373→func (l *LocalFS) newHandle(req *OpenRequest, host, name string, isDir bool) *localHandle {
374→	rel, _ := CleanPath(req.Path) // Resolve 已经校验过，这里不会失败
375→	return &localHandle{
376→		fs:            l,
377→		host:          host,
378→		rel:           rel,
379→		name:          name,
380→		isDir:         isDir,
381→		writable:      !l.cfg.ReadOnly && req.Flags&(OpenWrite|OpenAppend) != 0,
382→		writeThrough:  req.Flags&OpenWriteThrough != 0,
383→		deleteOnClose: req.Flags&OpenDeleteOnClose != 0,
384→	}
385→}
386→
387→// ---------------------------------------------------------------- 路径级操作
388→
389→// Stat 实现 FileSystem。
390→func (l *LocalFS) Stat(p string) (*Attr, error) {
391→	host, err := l.res.Resolve(p)
392→	if err != nil {
393→		return nil, err
394→	}
395→	rel, _ := CleanPath(p)
396→	return l.statHost(host, baseName(rel))
397→}
398→
399→// statHost 是所有属性查询的唯一出口，保证 Stat / ReadDir / Handle.Stat
400→// 给出的字段口径完全一致。
401→func (l *LocalFS) statHost(host, name string) (*Attr, error) {
402→	// 先 Stat（跟随软链，与 Samba 的默认行为一致；软链是否越界已由
403→	// Resolver 校验过）。目标不存在的悬空软链退回 Lstat，
404→	// 这样客户端至少能看到并删除它，而不是撞上一个查不到的幽灵条目。
405→	fi, err := os.Stat(host)
406→	if err != nil {
407→		if !os.IsNotExist(err) {
408→			return nil, mapError(err)
409→		}
410→		if fi, err = os.Lstat(host); err != nil {
411→			return nil, mapError(err)
412→		}
413→	}
414→	a := attrFromFileInfo(fi, name, l.cfg.ReadOnly)
415→	if bt, ok := statCreateTime(host); ok {
416→		a.CreateTime = bt
417→	}
418→	l.applyMetadata(host, a)
419→	return a, nil
420→}
421→
422→// applyMetadata 用旁路存储里的 POSIX 属主/权限覆盖 Attr。
423→// 只在宿主文件系统表达不了它们的平台上生效（AGENTS.md §5 P7）。
424→func (l *LocalFS) applyMetadata(host string, a *Attr) {
425→	if l.meta == nil {
426→		// Linux/macOS：宿主机原生就有 uid/gid/mode，直接采信。
427→		return
428→	}
429→	rel, err := filepath.Rel(l.res.Root(), host)
430→	if err != nil {
431→		rel = host
432→	}
433→	if md, ok := l.meta.Get(filepath.ToSlash(rel)); ok {
434→		a.UID, a.GID, a.Mode = md.UID, md.GID, md.Mode
435→		return
436→	}
437→	// 没有记录：用配置里的数字标签兜底，让客户端看到一个稳定的属主。
438→	a.UID, a.GID = l.cfg.UID, l.cfg.GID
439→
440→	// NTFS 没有 POSIX 权限位，attrFromFileInfo 在 Windows 上给不出 Mode。
441→	// 留 0 会让 macOS/Linux 客户端看到一个「谁都不能读写」的对象，
442→	// Time Machine 会直接判定备份目标不可用，所以必须兜一个合理默认值。
443→	if a.Mode == 0 {
444→		mode := l.cfg.FileMode
445→		if a.FileAttributes&FileAttributeDirectory != 0 {
446→			mode = l.cfg.DirMode
447→		}
448→		// 与 DOS 的 READONLY 位（以及只读共享）保持一致，避免客户端
449→		// 看到「权限位可写但一写就被拒」的矛盾状态。
450→		if a.FileAttributes&FileAttributeReadonly != 0 {
451→			mode &^= 0o222
452→		}
453→		a.Mode = uint32(mode.Perm())
454→	}
455→}
456→
457→// Remove 实现 FileSystem。文件与空目录都走这里。
458→func (l *LocalFS) Remove(p string) error {
459→	if l.cfg.ReadOnly {
460→		return ErrReadOnly
461→	}
462→	dir, name, err := l.res.ResolveParent(p)
463→	if err != nil {
464→		return err
465→	}
466→	host := filepath.Join(dir, name)
467→	if err := os.Remove(host); err != nil {
468→		return mapError(err)
469→	}
470→	l.forgetMetadata(host)
471→	return nil
472→}
473→
474→// Mkdir 实现 FileSystem。
475→func (l *LocalFS) Mkdir(p string, attrs uint32) error {
476→	if l.cfg.ReadOnly {
477→		return ErrReadOnly
478→	}
479→	dir, name, err := l.res.ResolveParent(p)
480→	if err != nil {
481→		return err
482→	}
483→	host := filepath.Join(dir, name)
484→	if err := os.Mkdir(host, l.cfg.DirMode); err != nil {
485→		return mapError(err)
486→	}
487→	// attrs 里客户端可能要求 HIDDEN/SYSTEM 等。POSIX 上除了 READONLY
488→	// 之外没有对应物，静默忽略（返回错误会让客户端认为 mkdir 失败）。
489→	if attrs&FileAttributeReadonly != 0 {
490→		_ = os.Chmod(host, l.cfg.DirMode&^0o222)
491→	}
492→	return nil
493→}
494→
495→// Rename 实现 FileSystem（对应 FileRenameInformation）。
496→func (l *LocalFS) Rename(oldPath, newPath string, replace bool) error {
497→	if l.cfg.ReadOnly {
498→		return ErrReadOnly
499→	}
500→	oldDir, oldName, err := l.res.ResolveParent(oldPath)
501→	if err != nil {
502→		return err
503→	}
504→	newDir, newName, err := l.res.ResolveParent(newPath)
505→	if err != nil {
506→		return err
507→	}
508→	src := filepath.Join(oldDir, oldName)
509→	dst := filepath.Join(newDir, newName)
510→
511→	// 大小写不敏感时 ResolveParent 会把 newName 折叠成磁盘上已存在的写法，
512→	// 于是 "a.txt" → "A.TXT" 这种**纯改大小写**的重命名会被当成同名 no-op 丢掉。
513→	// 用客户端原始路径的最后一个分量还原它真正想要的写法。
514→	//
515→	// 只在「同一父目录 + 仅大小写不同 + 折叠确实发生了」时才还原，
516→	// 此时目标必然就是 src 自己（sameObject），不能走下面的「目标已存在」分支：
517→	// 否则 replace=false 会误报 ErrExist，replace=true 会先把源文件删掉丢数据。
518→	sameObject := false
519→	if l.cfg.CaseInsensitive && oldDir == newDir && strings.EqualFold(oldName, newName) {
520→		if want := lastComponent(newPath); want != "" && want != newName {
521→			dst = filepath.Join(newDir, want)
522→			sameObject = true
523→		}
524→	}
525→
526→	if src == dst {
527→		return nil
528→	}
529→
530→	if _, err := os.Lstat(dst); err == nil {
531→		if !sameObject {
532→			if !replace {
533→				return ErrExist
534→			}
535→			// os.Rename 在 Windows 上不会覆盖已存在的目标，在 Unix 上会。
536→			// 统一先删再改名，保证行为一致。
537→			if err := os.Remove(dst); err != nil {
538→				return mapError(err)
539→			}
540→		}
541→	} else if !os.IsNotExist(err) {
542→		return mapError(err)
543→	}
544→
545→	if err := os.Rename(src, dst); err != nil {
546→		return mapError(err)
547→	}
548→	l.renameMetadata(src, dst)
549→	return nil
550→}
551→
552→// StatFS 实现 FileSystem。
553→func (l *LocalFS) StatFS() (*FSInfo, error) {
554→	info := &FSInfo{
555→		VolumeLabel:  l.label,
556→		VolumeSerial: l.serial,
557→		// 对客户端一律宣称大小写不敏感：这是 SMB/Windows 的语义，
558→		// 也是 Resolver 在做大小写回退查找时实际提供的行为。
559→		CaseSensitive:   false,
560→		MaxComponentLen: MaxComponentLen,
561→		BlockSize:       4096,
562→	}
563→	if err := platformStatFS(l.res.Root(), info); err != nil {
564→		return nil, err
565→	}
566→	if info.BlockSize == 0 {
567→		info.BlockSize = 4096
568→	}
569→	l.applyQuota(info)
570→	return info, nil
571→}
572→
573→// applyQuota 把上报的容量压到配额以内。
574→//
575→// 语义：配额限制的是**本共享**的总容量，所以
576→//
577→//	Total = min(宿主 Total, 配额)
578→//	Free  = min(宿主 Free,  配额 - 已用)
579→//
580→// 「已用」取共享自己的占用量还是宿主的占用量？这里取**宿主的**
581→// （Total-Free），理由是递归统计共享目录大小在十万级 band 目录上
582→// 要几秒钟，每次 QUERY_FS_INFO 都做一遍完全不可接受。
583→// 代价是：同一个宿主卷上放多个带配额的共享时，它们互相看得见对方的占用。
584→// 对 Time Machine 这个主要场景（一块盘一个备份共享）是准确的。
585→func (l *LocalFS) applyQuota(info *FSInfo) {
586→	if l.cfg.QuotaBytes == 0 {
587→		return
588→	}
589→	bs := uint64(info.BlockSize)
590→	if bs == 0 {
591→		return
592→	}
593→	// 向下取整成块数：宁可少报一点，也不要报出一个写不进去的容量。
594→	quotaBlocks := l.cfg.QuotaBytes / bs
595→
596→	usedBlocks := uint64(0)
597→	if info.TotalBlocks > info.FreeBlocks {
598→		usedBlocks = info.TotalBlocks - info.FreeBlocks
599→	}
600→
601→	var quotaFree uint64
602→	if quotaBlocks > usedBlocks {
603→		quotaFree = quotaBlocks - usedBlocks
604→	}
605→
606→	if quotaBlocks < info.TotalBlocks {
607→		info.TotalBlocks = quotaBlocks
608→	}
609→	if quotaFree < info.FreeBlocks {
610→		info.FreeBlocks = quotaFree
611→	}
612→
613→	// 收尾时强制维持 Avail <= Free <= Total。
614→	//
615→	// 少了这一步会在一种真实情况下倒挂：有些网络文件系统的 statfs
616→	// 会返回 Free > Total。那时 usedBlocks 被算成 0，配额剩余就没被压住，
617→	// 于是压完 Total 之后 Free 反而比 Total 大。
618→	// 客户端（尤其 Time Machine）会拿这几个数做减法，一旦倒挂就会
619→	// 算出天文数字的可用空间，然后一路写到真正的 ENOSPC。
620→	if info.FreeBlocks > info.TotalBlocks {
621→		info.FreeBlocks = info.TotalBlocks
622→	}
623→	if info.AvailBlocks > info.FreeBlocks {
624→		info.AvailBlocks = info.FreeBlocks
625→	}
626→}
627→
628→// Streams 实现 FileSystem，列出 alternate data stream
629→//（对应 SMB2 QUERY_INFO 的 FileStreamInformation）。
630→//
631→// 除主数据流外，还会报告存在的 AFP_AfpInfo / AFP_Resource ——
632→// macOS Finder 靠这个判断文件有没有资源派生与 FinderInfo。
633→func (l *LocalFS) Streams(p string) ([]StreamInfo, error) {
634→	base, stream, err := SplitStreamPath(p)
635→	if err != nil {
636→		return nil, err
637→	}
638→	if stream != "" {
639→		// 对一个流本身查询流列表是没有意义的请求。
640→		return nil, ErrInvalidPath
641→	}
642→	host, err := l.res.Resolve(base)
643→	if err != nil {
644→		return nil, err
645→	}
646→	a, err := l.statHost(host, baseName(base))
647→	if err != nil {
648→		return nil, err
649→	}
650→	return l.streamsOf(host, a), nil
651→}
652→
653→// ---------------------------------------------------------------- 小工具
654→
655→// baseName 取相对路径的末级名字；共享根返回 "."。
656→func baseName(rel string) string {
657→	if rel == "" {
658→		return "."
659→	}
660→	return path.Base(rel)
661→}
662→
663→// lastComponent 取客户端原始路径的最后一个分量（不做大小写折叠）。
664→func lastComponent(p string) string {
665→	comps, err := SplitPath(p)
666→	if err != nil || len(comps) == 0 {
667→		return ""
668→	}
669→	return comps[len(comps)-1]
670→}
671→
672→// forgetMetadata / renameMetadata 维护旁路存储与真实文件的一致性。
673→// meta 为 nil（Linux/macOS）时是空操作。
674→func (l *LocalFS) forgetMetadata(host string) {
675→	if l.meta == nil {
676→		return
677→	}
678→	if rel, err := filepath.Rel(l.res.Root(), host); err == nil {
679→		_ = l.meta.Delete(filepath.ToSlash(rel))
680→	}
681→}
682→
683→func (l *LocalFS) renameMetadata(src, dst string) {
684→	if l.meta == nil {
685→		return
686→	}
687→	relSrc, err1 := filepath.Rel(l.res.Root(), src)
688→	relDst, err2 := filepath.Rel(l.res.Root(), dst)
689→	if err1 != nil || err2 != nil {
690→		return
691→	}
692→	_ = l.meta.Rename(filepath.ToSlash(relSrc), filepath.ToSlash(relDst))
693→}
694→
695→// setTimes 设置访问/修改时间。未指定的一方保持原值。
696→func setTimes(host string, atime, mtime time.Time) error {
697→	if atime.IsZero() && mtime.IsZero() {
698→		return nil
699→	}
700→	if atime.IsZero() || mtime.IsZero() {
701→		fi, err := os.Stat(host)
702→		if err != nil {
703→			return mapError(err)
704→		}
705→		if atime.IsZero() {
706→			atime = fi.ModTime()
707→		}
708→		if mtime.IsZero() {
709→			mtime = fi.ModTime()
710→		}
711→	}
712→	if err := os.Chtimes(host, atime, mtime); err != nil {
713→		return mapError(err)
714→	}
715→	return nil
716→}
