  1→package vfs
  2→
  3→// local.go —— FileSystem 接口的本地磁盘实现。
  4→//
  5→// 职责边界：
  6→//   - **所有**来自客户端的路径都必须先过 Resolver（安全边界，AGENTS.md §8）；
  7→//   - **所有**宿主机错误都必须过 mapError 收敛成 sentinel，
  8→//     绝不能把 *os.PathError 泄漏给 SMB 层（否则 NTSTATUS 会退化成
  9→//     STATUS_UNSUCCESSFUL，客户端行为会变得难以预测）；
 10→//   - 只读共享在**入口**就拒绝所有写意图，不依赖宿主机的权限位。
 11→
 12→import (
 13→	"hash/fnv"
 14→	"io/fs"
 15→	"os"
 16→	"path"
 17→	"path/filepath"
 18→	"strings"
 19→	"sync"
 20→	"time"
 21→)
 22→
 23→// LocalConfig 是构造 LocalFS 所需的参数。
 24→//
 25→// 注意 UID/GID：按 AGENTS.md §1.1，它们只是**给 VFS 层用的数字标签**，
 26→// 不做系统用户解析，也不要求宿主机上真的存在这个用户。
 27→type LocalConfig struct {
 28→	// Root 是共享根目录的宿主机路径，必须已存在且是目录。
 29→	Root string
 30→
 31→	// ReadOnly 为 true 时所有写操作返回 ErrReadOnly。
 32→	ReadOnly bool
 33→
 34→	// CaseInsensitive 打开大小写不敏感的回退查找（SMB 语义）。
 35→	// 建议置 true：Windows 客户端经常用与磁盘上不同的大小写来打开文件。
 36→	CaseInsensitive bool
 37→
 38→	// VolumeLabel 是卷标，空则用共享根的目录名。
 39→	VolumeLabel string
 40→
 41→	// UID / GID 是报给客户端的属主标签。
 42→	// 仅在宿主文件系统表达不了属主时（Windows）作为默认值使用。
 43→	UID, GID uint32
 44→
 45→	// FileMode / DirMode 是新建文件/目录的权限位，0 表示用默认值。
 46→	FileMode fs.FileMode
 47→	DirMode  fs.FileMode
 48→
 49→	// MetadataPath 是旁路元数据库的路径（仅 Windows 使用，见 AGENTS.md §5 P7）。
 50→	// 空则放在 Root 下的默认位置。
 51→	MetadataPath string
 52→
 53→	// QuotaBytes 限制**向客户端上报**的卷容量（字节），0 表示不限。
 54→	//
 55→	// Time Machine 会一直备份到把整个卷吃满为止，所以真实 NAS 都提供
 56→	// 给 TM 共享设配额的能力。设了以后 StatFS 按 min(宿主真实值, 配额) 上报。
 57→	//
 58→	// 这**不是**强制配额：只影响上报的数字，不阻止本地写入。
 59→	// 真正的强制配额要靠宿主文件系统，不在本软件职责范围内。
 60→	QuotaBytes uint64
 61→}
 62→
 63→const (
 64→	defaultFileMode fs.FileMode = 0o644
 65→	defaultDirMode  fs.FileMode = 0o755
 66→)
 67→
 68→// LocalFS 把宿主机的一个目录导出为 SMB 共享。
 69→//
 70→// 并发安全：所有方法可被多 goroutine 并发调用。
 71→type LocalFS struct {
 72→	res *Resolver
 73→	cfg LocalConfig
 74→
 75→	label  string
 76→	serial uint32
 77→
 78→	// meta 是 POSIX 属主/权限的旁路存储，只在宿主文件系统表达不了它们的
 79→	// 平台（Windows）上非 nil。Linux/macOS 上恒为 nil，零开销。
 80→	meta MetadataStore
 81→
 82→	closeOnce sync.Once
 83→}
 84→
 85→// 编译期断言：LocalFS 必须满足 FileSystem 契约。
 86→var _ FileSystem = (*LocalFS)(nil)
 87→
 88→// NewLocalFS 构造一个本地磁盘共享。
 89→func NewLocalFS(cfg LocalConfig) (*LocalFS, error) {
 90→	res, err := NewResolver(cfg.Root, cfg.CaseInsensitive)
 91→	if err != nil {
 92→		return nil, err
 93→	}
 94→	if cfg.FileMode == 0 {
 95→		cfg.FileMode = defaultFileMode
 96→	}
 97→	if cfg.DirMode == 0 {
 98→		cfg.DirMode = defaultDirMode
 99→	}
100→
101→	label := cfg.VolumeLabel
102→	if label == "" {
103→		label = filepath.Base(res.Root())
104→	}
105→
106→	l := &LocalFS{
107→		res:    res,
108→		cfg:    cfg,
109→		label:  label,
110→		serial: volumeSerial(res.Root()),
111→	}
112→
113→	meta, err := openMetadataStore(res.Root(), cfg.MetadataPath)
114→	if err != nil {
115→		return nil, err
116→	}
117→	l.meta = meta
118→	return l, nil
119→}
120→
121→// volumeSerial 由共享根路径派生一个稳定的卷序列号。
122→//
123→// 为什么要稳定：Windows 客户端会缓存 (VolumeSerial, FileID) 作为文件身份，
124→// 服务重启后序列号变了会导致客户端缓存失效甚至误判文件被替换。
125→// 用路径哈希而不是随机数正是为了跨重启稳定。
126→func volumeSerial(root string) uint32 {
127→	h := fnv.New32a()
128→	_, _ = h.Write([]byte(root))
129→	s := h.Sum32()
130→	if s == 0 {
131→		s = 1 // 0 在部分客户端里被当作「无效卷」
132→	}
133→	return s
134→}
135→
136→// Root 返回共享根的宿主机绝对路径（供测试与日志用）。
137→func (l *LocalFS) Root() string { return l.res.Root() }
138→
139→// ReadOnly 实现 FileSystem。
140→func (l *LocalFS) ReadOnly() bool { return l.cfg.ReadOnly }
141→
142→// Close 实现 FileSystem。
143→func (l *LocalFS) Close() error {
144→	var err error
145→	l.closeOnce.Do(func() {
146→		if l.meta != nil {
147→			err = l.meta.Close()
148→		}
149→	})
150→	return err
151→}
152→
153→// ---------------------------------------------------------------- Open
154→
155→// Open 实现 FileSystem，把 SMB2 CREATE 的语义落到 os.OpenFile 上。
156→func (l *LocalFS) Open(req *OpenRequest) (Handle, Action, error) {
157→	if req == nil {
158→		return nil, 0, ErrInvalidArg
159→	}
160→	if l.cfg.ReadOnly && dispositionWrites(req.Disposition, req.Flags) {
161→		return nil, 0, ErrReadOnly
162→	}
163→
164→	// 流名有两个来源：显式的 req.Stream，以及路径里的 "file:stream:$DATA"
165→	// 语法。后者是 macOS 客户端常用的写法，必须在 Resolve **之前**剥掉，
166→	// 否则冒号会被当成非法文件名字符而拒绝掉一个合法请求。
167→	reqPath, stream := req.Path, req.Stream
168→	if stream == "" {
169→		var err error
170→		if reqPath, stream, err = SplitStreamPath(req.Path); err != nil {
171→			return nil, 0, err
172→		}
173→	} else if err := ValidateStreamName(stream); err != nil {
174→		return nil, 0, err
175→	}
176→
177→	host, err := l.res.Resolve(reqPath)
178→	if err != nil {
179→		return nil, 0, err
180→	}
181→	name := path.Base("/" + reqPath) // 根目录时得到 "/"，下面会归一
182→	if reqPath == "" {
183→		name = "."
184→	}
185→
186→	if stream != "" {
187→		return l.openStream(req, host, name, stream)
188→	}
189→
190→	fi, statErr := os.Lstat(host)
191→	exists := statErr == nil
192→	if statErr != nil && !os.IsNotExist(statErr) {
193→		return nil, 0, mapError(statErr)
194→	}
195→
196→	// 软链：Resolve 已确认其目标在共享内，这里求值成实路径，
197→	// 以便后面带 O_NOFOLLOW 打开时不会被 ELOOP 挡住（见 EvalFinal 的说明）。
198→	if exists && fi.Mode()&fs.ModeSymlink != 0 && req.Flags&OpenNoFollow == 0 {
199→		real, err := l.res.EvalFinal(host)
200→		if err != nil {
201→			return nil, 0, err
202→		}
203→		host = real
204→		if fi, err = os.Lstat(host); err != nil {
205→			return nil, 0, mapError(err)
206→		}
207→	}
208→
209→	isDir := exists && fi.IsDir()
210→	wantDir := req.Flags&OpenDirectory != 0
211→
212→	switch {
213→	case exists && isDir && req.Flags&OpenNonDirectory != 0:
214→		// FILE_NON_DIRECTORY_FILE 遇到目录 → STATUS_FILE_IS_A_DIRECTORY
215→		return nil, 0, ErrIsDir
216→	case exists && !isDir && wantDir:
217→		// FILE_DIRECTORY_FILE 遇到文件 → STATUS_NOT_A_DIRECTORY
218→		return nil, 0, ErrNotDir
219→	}
220→
221→	if isDir || (!exists && wantDir) {
222→		return l.openDir(req, host, name, exists)
223→	}
224→	return l.openFile(req, host, name, exists)
225→}
226→
227→// dispositionWrites 判断这次 CREATE 是否带有写意图。
228→// 只读共享在入口就要挡掉，不能等到真正写的时候才失败 ——
229→// 客户端拿到句柄之后会认为写一定成功。
230→func dispositionWrites(d Disposition, f OpenFlags) bool {
231→	if f&(OpenWrite|OpenAppend|OpenDeleteOnClose) != 0 {
232→		return true
233→	}
234→	switch d {
235→	case Supersede, CreateNew, OpenAlways, TruncateExisting, TruncateAlways:
236→		return true
237→	}
238→	return false
239→}
240→
241→// openDir 处理目录的打开与创建。
242→func (l *LocalFS) openDir(req *OpenRequest, host, name string, exists bool) (Handle, Action, error) {
243→	action := ActionOpened
244→
245→	if !exists {
246→		switch req.Disposition {
247→		case CreateNew, OpenAlways, TruncateAlways, Supersede:
248→			if err := os.Mkdir(host, l.cfg.DirMode); err != nil {
249→				return nil, 0, mapError(err)
250→			}
251→			action = ActionCreated
252→		default: // OpenExisting / TruncateExisting
253→			return nil, 0, ErrNotFound
254→		}
255→	} else {
256→		switch req.Disposition {
257→		case CreateNew:
258→			return nil, 0, ErrExist
259→		case Supersede, TruncateExisting, TruncateAlways:
260→			// 目录无法被截断/取代。Windows 在这里返回
261→			// STATUS_INVALID_PARAMETER，我们用 ErrIsDir 表达「对象是目录」。
262→			return nil, 0, ErrIsDir
263→		}
264→	}
265→
266→	h := l.newHandle(req, host, name, true)
267→	if req.Flags&OpenAttrOnly != 0 {
268→		return h, action, nil
269→	}
270→	// 目录只需读句柄：SMB 对目录的「写」是 SET_INFO（改属性/改名），
271→	// 那些操作走路径而不是 fd。
272→	f, err := os.OpenFile(host, os.O_RDONLY|openNoFollow, 0)
273→	if err != nil {
274→		return nil, 0, mapError(err)
275→	}
276→	h.f = f
277→	return h, action, nil
278→}
279→
280→// openFile 处理普通文件的打开与创建，实现 MS-SMB2 §2.2.13 的
281→// CreateDisposition 语义（对照表见 docs/protocol-notes.md §8）。
282→func (l *LocalFS) openFile(req *OpenRequest, host, name string, exists bool) (Handle, Action, error) {
283→	var (
284→		flag   int
285→		action Action
286→	)
287→	switch req.Disposition {
288→	case Supersede:
289→		// 「删除重建」：语义上原文件的属性、ADS 都应被丢弃。
290→		// 用 O_TRUNC 近似（内容清空、inode 保留）。
291→		// TODO: 严格实现需 unlink + create，但那会破坏其他已打开句柄，
292→		//       且 Windows 客户端极少用 SUPERSEDE，先按 Samba 的做法来。
293→		flag = os.O_CREATE | os.O_TRUNC
294→		if exists {
295→			action = ActionSuperseded
296→		} else {
297→			action = ActionCreated
298→		}
299→	case OpenExisting:
300→		if !exists {
301→			return nil, 0, ErrNotFound
302→		}
303→		action = ActionOpened
304→	case CreateNew:
305→		// O_EXCL 让「存在则失败」是原子的，不依赖上面的 lstat 结果。
306→		flag = os.O_CREATE | os.O_EXCL
307→		action = ActionCreated
308→	case OpenAlways:
309→		flag = os.O_CREATE
310→		if exists {
311→			action = ActionOpened
312→		} else {
313→			action = ActionCreated
314→		}
315→	case TruncateExisting:
316→		if !exists {
317→			return nil, 0, ErrNotFound
318→		}
319→		flag = os.O_TRUNC
320→		action = ActionOverwritten
321→	case TruncateAlways:
322→		flag = os.O_CREATE | os.O_TRUNC
323→		if exists {
324→			action = ActionOverwritten
325→		} else {
326→			action = ActionCreated
327→		}
328→	default:
329→		return nil, 0, ErrInvalidArg
330→	}
331→
332→	h := l.newHandle(req, host, name, false)
333→
334→	// 仅查属性：不真的 open。Explorer 会对目录里每个文件做一次属性探测，
335→	// 省下这一次 open/close 对大目录的收益很大（docs/protocol-notes.md §8）。
336→	// 注意此时若文件不存在且 disposition 要求创建，仍需真的创建出来。
337→	if req.Flags&OpenAttrOnly != 0 && flag&os.O_CREATE == 0 && flag&os.O_TRUNC == 0 {
338→		return h, action, nil
339→	}
340→
341→	f, err := os.OpenFile(host, flag|accessFlags(req.Flags, flag)|openNoFollow, l.cfg.FileMode)
342→	if err != nil {
343→		return nil, 0, mapError(err)
344→	}
345→	h.f = f
346→	return h, action, nil
347→}
348→
349→// accessFlags 把 OpenFlags 的读写意图翻译成 O_RDONLY/O_WRONLY/O_RDWR。
350→//
351→// 两点特别说明：
352→//
353→//  1. **绝不设置 O_APPEND**。SMB2 WRITE 永远带显式 offset（pwrite 语义），
354→//     O_APPEND 会让内核忽略 offset 把数据全追加到尾部，导致文件内容错乱。
355→//     协议里的「追加」是客户端发 offset=0xFFFFFFFFFFFFFFFF，
356→//     由 server 层换算成当前 EOF，不需要内核帮忙。
357→//  2. 若 disposition 要求 O_TRUNC/O_CREATE，即使客户端只请求了读权限，
358→//     也必须至少有写权限，否则 open 会 EACCES。
359→func accessFlags(f OpenFlags, dispFlag int) int {
360→	wantWrite := f&(OpenWrite|OpenAppend) != 0 || dispFlag&(os.O_TRUNC|os.O_CREATE) != 0
361→	wantRead := f&OpenRead != 0 || !wantWrite
362→
363→	switch {
364→	case wantRead && wantWrite:
365→		return os.O_RDWR
366→	case wantWrite:
367→		return os.O_WRONLY
368→	default:
369→		return os.O_RDONLY
370→	}
371→}
