387→// ---------------------------------------------------------------- 路径级操作
388→
389→// Stat 实现 FileSystem。
390→func (l *LocalFS) Stat(p string) (*Attr, error) {
391→	host, err := l.res.Resolve(p)
392→	if err != nil {
393→		return nil, err
394→	}
395→	rel, _ := CleanPath(p)
396→	return l.statHost(host, baseName(rel))
397→}
398→
399→// statHost 是所有属性查询的唯一出口，保证 Stat / ReadDir / Handle.Stat
400→// 给出的字段口径完全一致。
401→func (l *LocalFS) statHost(host, name string) (*Attr, error) {
402→	// 先 Stat（跟随软链，与 Samba 的默认行为一致；软链是否越界已由
403→	// Resolver 校验过）。目标不存在的悬空软链退回 Lstat，
404→	// 这样客户端至少能看到并删除它，而不是撞上一个查不到的幽灵条目。
405→	fi, err := os.Stat(host)
406→	if err != nil {
407→		if !os.IsNotExist(err) {
408→			return nil, mapError(err)
409→		}
410→		if fi, err = os.Lstat(host); err != nil {
411→			return nil, mapError(err)
412→		}
413→	}
414→	a := attrFromFileInfo(fi, name, l.cfg.ReadOnly)
415→	if bt, ok := statCreateTime(host); ok {
416→		a.CreateTime = bt
417→	}
418→	l.applyMetadata(host, a)
419→	return a, nil
420→}
421→
422→// applyMetadata 用旁路存储里的 POSIX 属主/权限覆盖 Attr。
423→// 只在宿主文件系统表达不了它们的平台上生效（AGENTS.md §5 P7）。
424→func (l *LocalFS) applyMetadata(host string, a *Attr) {
425→	if l.meta == nil {
426→		// Linux/macOS：宿主机原生就有 uid/gid/mode，直接采信。
427→		return
428→	}
429→	rel, err := filepath.Rel(l.res.Root(), host)
430→	if err != nil {
431→		rel = host
432→	}
433→	if md, ok := l.meta.Get(filepath.ToSlash(rel)); ok {
434→		a.UID, a.GID, a.Mode = md.UID, md.GID, md.Mode
435→		return
436→	}
437→	// 没有记录：用配置里的数字标签兜底，让客户端看到一个稳定的属主。
438→	a.UID, a.GID = l.cfg.UID, l.cfg.GID
439→
440→	// NTFS 没有 POSIX 权限位，attrFromFileInfo 在 Windows 上给不出 Mode。
441→	// 留 0 会让 macOS/Linux 客户端看到一个「谁都不能读写」的对象，
442→	// Time Machine 会直接判定备份目标不可用，所以必须兜一个合理默认值。
443→	if a.Mode == 0 {
444→		mode := l.cfg.FileMode
445→		if a.FileAttributes&FileAttributeDirectory != 0 {
446→			mode = l.cfg.DirMode
447→		}
448→		// 与 DOS 的 READONLY 位（以及只读共享）保持一致，避免客户端
449→		// 看到「权限位可写但一写就被拒」的矛盾状态。
450→		if a.FileAttributes&FileAttributeReadonly != 0 {
451→			mode &^= 0o222
452→		}
453→		a.Mode = uint32(mode.Perm())
454→	}
455→}
456→
457→// Remove 实现 FileSystem。文件与空目录都走这里。
458→func (l *LocalFS) Remove(p string) error {
459→	if l.cfg.ReadOnly {
460→		return ErrReadOnly
461→	}
462→	dir, name, err := l.res.ResolveParent(p)
463→	if err != nil {
464→		return err
465→	}
466→	host := filepath.Join(dir, name)
467→	if err := os.Remove(host); err != nil {
468→		return mapError(err)
469→	}
470→	l.forgetMetadata(host)
471→	return nil
472→}
473→
474→// Mkdir 实现 FileSystem。
475→func (l *LocalFS) Mkdir(p string, attrs uint32) error {
476→	if l.cfg.ReadOnly {
477→		return ErrReadOnly
478→	}
479→	dir, name, err := l.res.ResolveParent(p)
480→	if err != nil {
481→		return err
482→	}
483→	host := filepath.Join(dir, name)
484→	if err := os.Mkdir(host, l.cfg.DirMode); err != nil {
485→		return mapError(err)
486→	}
487→	// attrs 里客户端可能要求 HIDDEN/SYSTEM 等。POSIX 上除了 READONLY
488→	// 之外没有对应物，静默忽略（返回错误会让客户端认为 mkdir 失败）。
489→	if attrs&FileAttributeReadonly != 0 {
490→		_ = os.Chmod(host, l.cfg.DirMode&^0o222)
491→	}
492→	return nil
493→}
494→
495→// Rename 实现 FileSystem（对应 FileRenameInformation）。
496→func (l *LocalFS) Rename(oldPath, newPath string, replace bool) error {
497→	if l.cfg.ReadOnly {
498→		return ErrReadOnly
499→	}
500→	oldDir, oldName, err := l.res.ResolveParent(oldPath)
501→	if err != nil {
502→		return err
503→	}
504→	newDir, newName, err := l.res.ResolveParent(newPath)
505→	if err != nil {
506→		return err
507→	}
508→	src := filepath.Join(oldDir, oldName)
509→	dst := filepath.Join(newDir, newName)
510→
511→	// 大小写不敏感时 ResolveParent 会把 newName 折叠成磁盘上已存在的写法，
512→	// 于是 "a.txt" → "A.TXT" 这种**纯改大小写**的重命名会被当成同名 no-op 丢掉。
513→	// 用客户端原始路径的最后一个分量还原它真正想要的写法。
514→	//
515→	// 只在「同一父目录 + 仅大小写不同 + 折叠确实发生了」时才还原，
516→	// 此时目标必然就是 src 自己（sameObject），不能走下面的「目标已存在」分支：
517→	// 否则 replace=false 会误报 ErrExist，replace=true 会先把源文件删掉丢数据。
518→	sameObject := false
519→	if l.cfg.CaseInsensitive && oldDir == newDir && strings.EqualFold(oldName, newName) {
520→		if want := lastComponent(newPath); want != "" && want != newName {
521→			dst = filepath.Join(newDir, want)
522→			sameObject = true
523→		}
524→	}
525→
526→	if src == dst {
527→		return nil
528→	}
529→
530→	if _, err := os.Lstat(dst); err == nil {
531→		if !sameObject {
532→			if !replace {
533→				return ErrExist
534→			}
535→			// os.Rename 在 Windows 上不会覆盖已存在的目标，在 Unix 上会。
536→			// 统一先删再改名，保证行为一致。
537→			if err := os.Remove(dst); err != nil {
538→				return mapError(err)
539→			}
540→		}
541→	} else if !os.IsNotExist(err) {
542→		return mapError(err)
543→	}
544→
545→	if err := os.Rename(src, dst); err != nil {
546→		return mapError(err)
547→	}
548→	l.renameMetadata(src, dst)
549→	return nil
550→}
551→
552→// StatFS 实现 FileSystem。
553→func (l *LocalFS) StatFS() (*FSInfo, error) {
554→	info := &FSInfo{
555→		VolumeLabel:  l.label,
556→		VolumeSerial: l.serial,
557→		// 对客户端一律宣称大小写不敏感：这是 SMB/Windows 的语义，
558→		// 也是 Resolver 在做大小写回退查找时实际提供的行为。
559→		CaseSensitive:   false,
560→		MaxComponentLen: MaxComponentLen,
561→		BlockSize:       4096,
562→	}
563→	if err := platformStatFS(l.res.Root(), info); err != nil {
564→		return nil, err
565→	}
566→	if info.BlockSize == 0 {
567→		info.BlockSize = 4096
568→	}
569→	l.applyQuota(info)
570→	return info, nil
571→}
572→
573→// applyQuota 把上报的容量压到配额以内。
574→//
575→// 语义：配额限制的是**本共享**的总容量，所以
576→//
577→//	Total = min(宿主 Total, 配额)
578→//	Free  = min(宿主 Free,  配额 - 已用)
579→//
580→// 「已用」取共享自己的占用量还是宿主的占用量？这里取**宿主的**
581→// （Total-Free），理由是递归统计共享目录大小在十万级 band 目录上
582→// 要几秒钟，每次 QUERY_FS_INFO 都做一遍完全不可接受。
583→// 代价是：同一个宿主卷上放多个带配额的共享时，它们互相看得见对方的占用。
584→// 对 Time Machine 这个主要场景（一块盘一个备份共享）是准确的。
585→func (l *LocalFS) applyQuota(info *FSInfo) {
586→	if l.cfg.QuotaBytes == 0 {
587→		return
588→	}
589→	bs := uint64(info.BlockSize)
590→	if bs == 0 {
591→		return
592→	}
593→	// 向下取整成块数：宁可少报一点，也不要报出一个写不进去的容量。
594→	quotaBlocks := l.cfg.QuotaBytes / bs
595→
596→	usedBlocks := uint64(0)
597→	if info.TotalBlocks > info.FreeBlocks {
598→		usedBlocks = info.TotalBlocks - info.FreeBlocks
599→	}
600→
601→	var quotaFree uint64
602→	if quotaBlocks > usedBlocks {
603→		quotaFree = quotaBlocks - usedBlocks
604→	}
605→
606→	if quotaBlocks < info.TotalBlocks {
607→		info.TotalBlocks = quotaBlocks
608→	}
609→	if quotaFree < info.FreeBlocks {
610→		info.FreeBlocks = quotaFree
611→	}
612→
613→	// 收尾时强制维持 Avail <= Free <= Total。
614→	//
615→	// 少了这一步会在一种真实情况下倒挂：有些网络文件系统的 statfs
616→	// 会返回 Free > Total。那时 usedBlocks 被算成 0，配额剩余就没被压住，
617→	// 于是压完 Total 之后 Free 反而比 Total 大。
618→	// 客户端（尤其 Time Machine）会拿这几个数做减法，一旦倒挂就会
619→	// 算出天文数字的可用空间，然后一路写到真正的 ENOSPC。
620→	if info.FreeBlocks > info.TotalBlocks {
621→		info.FreeBlocks = info.TotalBlocks
622→	}
623→	if info.AvailBlocks > info.FreeBlocks {
624→		info.AvailBlocks = info.FreeBlocks
625→	}
626→}
627→
628→// Streams 实现 FileSystem，列出 alternate data stream
629→//（对应 SMB2 QUERY_INFO 的 FileStreamInformation）。
630→//
631→// 除主数据流外，还会报告存在的 AFP_AfpInfo / AFP_Resource ——
632→// macOS Finder 靠这个判断文件有没有资源派生与 FinderInfo。
633→func (l *LocalFS) Streams(p string) ([]StreamInfo, error) {
634→	base, stream, err := SplitStreamPath(p)
635→	if err != nil {
636→		return nil, err
637→	}
638→	if stream != "" {
639→		// 对一个流本身查询流列表是没有意义的请求。
640→		return nil, ErrInvalidPath
641→	}
642→	host, err := l.res.Resolve(base)
643→	if err != nil {
644→		return nil, err
645→	}
646→	a, err := l.statHost(host, baseName(base))
647→	if err != nil {
648→		return nil, err
649→	}
650→	return l.streamsOf(host, a), nil
651→}
652→
653→// ---------------------------------------------------------------- 小工具
654→
655→// baseName 取相对路径的末级名字；共享根返回 "."。
656→func baseName(rel string) string {
657→	if rel == "" {
658→		return "."
659→	}
660→	return path.Base(rel)
661→}
662→
663→// lastComponent 取客户端原始路径的最后一个分量（不做大小写折叠）。
664→func lastComponent(p string) string {
665→	comps, err := SplitPath(p)
666→	if err != nil || len(comps) == 0 {
667→		return ""
668→	}
669→	return comps[len(comps)-1]
670→}
671→
672→// forgetMetadata / renameMetadata 维护旁路存储与真实文件的一致性。
673→// meta 为 nil（Linux/macOS）时是空操作。
674→func (l *LocalFS) forgetMetadata(host string) {
675→	if l.meta == nil {
676→		return
677→	}
678→	if rel, err := filepath.Rel(l.res.Root(), host); err == nil {
679→		_ = l.meta.Delete(filepath.ToSlash(rel))
680→	}
681→}
682→
683→func (l *LocalFS) renameMetadata(src, dst string) {
684→	if l.meta == nil {
685→		return
686→	}
687→	relSrc, err1 := filepath.Rel(l.res.Root(), src)
688→	relDst, err2 := filepath.Rel(l.res.Root(), dst)
689→	if err1 != nil || err2 != nil {
690→		return
691→	}
692→	_ = l.meta.Rename(filepath.ToSlash(relSrc), filepath.ToSlash(relDst))
693→}
694→
695→// setTimes 设置访问/修改时间。未指定的一方保持原值。
696→func setTimes(host string, atime, mtime time.Time) error {
697→	if atime.IsZero() && mtime.IsZero() {
698→		return nil
699→	}
700→	if atime.IsZero() || mtime.IsZero() {
701→		fi, err := os.Stat(host)
702→		if err != nil {
703→			return mapError(err)
704→		}
705→		if atime.IsZero() {
706→			atime = fi.ModTime()
707→		}
708→		if mtime.IsZero() {
709→			mtime = fi.ModTime()
710→		}
711→	}
712→	if err := os.Chtimes(host, atime, mtime); err != nil {
713→		return mapError(err)
714→	}
715→	return nil
716→}
