  3→// stream_handle.go —— alternate data stream 的句柄实现。
  4→//
  5→// 两种流的存储形态差别很大，但对 SMB 层必须表现成同一种东西
  6→// （一个可读写、有长度、能 Truncate 的字节流），所以统一封装成 streamHandle：
  7→//
  8→//	AFP_AfpInfo   内存缓冲（固定 60 字节），Close/Flush 时整体回写 xattr
  9→//	AFP_Resource  ._ 旁路文件，所有偏移加上 AppleDouble 头长度
 10→//
 11→// AFP_AfpInfo 用内存缓冲而不是直接映射 xattr 的原因：xattr 只能整体
 12→// 读写，没有「在偏移 16 处写 4 字节」这种语义，而客户端确实会分段写。
 13→
 14→import (
 15→	"io"
 16→	"os"
 17→	"sync"
 18→)
 19→
 20→// streamHandle 实现 Handle。
 21→type streamHandle struct {
 22→	fs   *LocalFS
 23→	host string // 基础对象的宿主机路径
 24→	name string // 基础对象名（用于 Attr.Name）
 25→	slot string // 规范化后的流名
 26→
 27→	mu     sync.Mutex
 28→	closed bool
 29→
 30→	writable bool
 31→
 32→	// AFP_AfpInfo：内存缓冲 + 脏标记。
 33→	buf   []byte
 34→	dirty bool
 35→
 36→	// AFP_Resource：旁路文件 + 数据段起始偏移。
 37→	f       *os.File
 38→	dataOff int64
 39→}
 40→
 41→var _ Handle = (*streamHandle)(nil)
 42→
 43→// openStream 打开 alternate data stream。
 44→//
 45→// 基础对象必须已存在：SMB 不允许「只创建流不创建文件」，
 46→// 客户端总是先 CREATE 文件本体再 CREATE 它的流。
 47→func (l *LocalFS) openStream(req *OpenRequest, host, name, stream string) (Handle, Action, error) {
 48→	slot := canonicalStreamName(stream)
 49→	if !IsAFPStream(slot) {
 50→		// 通用 ADS 不支持。明确拒绝，不要假装成功（见 stream_store.go 说明）。
 51→		return nil, 0, ErrNotSupported
 52→	}
 53→
 54→	fi, err := os.Lstat(host)
 55→	if err != nil {
 56→		return nil, 0, mapError(err)
 57→	}
 58→	if fi.IsDir() {
 59→		// 目录上的 AFP 流：Samba 也只在文件上支持，目录的 FinderInfo
 60→		// 走 ._ 同名文件那套，不在本阶段范围内。
 61→		return nil, 0, ErrNotSupported
 62→	}
 63→
 64→	writes := dispositionWrites(req.Disposition, req.Flags)
 65→	if writes && l.cfg.ReadOnly {
 66→		return nil, 0, ErrReadOnly
 67→	}
 68→	writable := writes || req.Flags&OpenWrite != 0
 69→
 70→	h := &streamHandle{
 71→		fs: l, host: host, name: name, slot: slot, writable: writable,
 72→	}
 73→
 74→	if slot == StreamAFPInfo {
 75→		return h.openAfpInfo(req)
 76→	}
 77→	return h.openResource(req)
 78→}
 79→
 80→// openAfpInfo 准备 AFP_AfpInfo 流的内存缓冲。
 81→func (h *streamHandle) openAfpInfo(req *OpenRequest) (Handle, Action, error) {
 82→	ai, err := h.fs.readAfpInfo(h.host)
 83→	exists := err == nil
 84→	if err != nil && err != ErrNotFound {
 85→		if err == ErrNotSupported {
 86→			// 宿主文件系统没有 xattr（比如挂载时关了 user_xattr）。
 87→			// 这不是客户端的错，但也没法支持 —— 明确告知。
 88→			return nil, 0, ErrNotSupported
 89→		}
 90→		return nil, 0, err
 91→	}
 92→
 93→	action, err := streamAction(req.Disposition, exists)
 94→	if err != nil {
 95→		return nil, 0, err
 96→	}
 97→	if !exists || action == ActionSuperseded || action == ActionOverwritten {
 98→		ai = NewAfpInfo()
 99→		// 新建/覆盖时立刻落盘一个空流，这样后续的 Streams() 能看到它。
100→		// 注意 writeAfpInfo 对全零 FinderInfo 是「删除」语义，
101→		// 所以这里不写 —— 流的存在性由第一次真正的写入建立。
102→	}
103→
104→	h.buf = ai.Marshal()
105→	return h, action, nil
106→}
107→
108→// openResource 准备 AFP_Resource 流的旁路文件。
109→func (h *streamHandle) openResource(req *OpenRequest) (Handle, Action, error) {
110→	_, exists := resourceForkSize(dotUnderscoreName(h.host))
111→
112→	action, err := streamAction(req.Disposition, exists)
113→	if err != nil {
114→		return nil, 0, err
115→	}
116→
117→	create := action == ActionCreated || action == ActionSuperseded
118→	f, dataOff, err := h.fs.openResourceFork(h.host, h.writable, create || h.writable)
119→	if err != nil {
120→		return nil, 0, err
121→	}
122→	h.f, h.dataOff = f, dataOff
123→
124→	if action == ActionSuperseded || action == ActionOverwritten {
125→		if err := h.truncateLocked(0); err != nil {
126→			_ = f.Close()
127→			return nil, 0, err
128→		}
129→	}
130→	return h, action, nil
131→}
132→
133→// streamAction 把 CreateDisposition 映射成流上的 Action。
134→//
135→// 语义与主数据流一致（MS-SMB2 §2.2.13 / §2.2.14），
136→// 单独写一份是因为流没有「目录」这条分支，混在一起反而难读。
137→func streamAction(d Disposition, exists bool) (Action, error) {
138→	switch d {
139→	case Supersede:
140→		if exists {
141→			return ActionSuperseded, nil
142→		}
143→		return ActionCreated, nil
144→	case OpenExisting:
145→		if !exists {
146→			return 0, ErrNotFound
147→		}
148→		return ActionOpened, nil
149→	case CreateNew:
150→		if exists {
151→			return 0, ErrExist
152→		}
153→		return ActionCreated, nil
154→	case OpenAlways:
155→		if exists {
156→			return ActionOpened, nil
157→		}
158→		return ActionCreated, nil
159→	case TruncateExisting:
160→		if !exists {
161→			return 0, ErrNotFound
162→		}
163→		return ActionOverwritten, nil
164→	case TruncateAlways:
165→		if exists {
166→			return ActionOverwritten, nil
167→		}
168→		return ActionCreated, nil
169→	}
170→	return 0, ErrInvalidArg
171→}
172→
173→// ---------------------------------------------------------------- IO
174→
175→func (h *streamHandle) ReadAt(p []byte, off int64) (int, error) {
176→	if err := checkRange(off, len(p)); err != nil {
177→		return 0, err
178→	}
179→	h.mu.Lock()
180→	defer h.mu.Unlock()
181→	if h.closed {
182→		return 0, ErrClosed
183→	}
184→
185→	if h.f == nil {
186→		// AFP_AfpInfo：从内存缓冲读。
187→		if off >= int64(len(h.buf)) {
188→			return 0, io.EOF
189→		}
190→		n := copy(p, h.buf[off:])
191→		if n < len(p) {
192→			return n, io.EOF
193→		}
194→		return n, nil
195→	}
196→
197→	// AFP_Resource：偏移平移到数据段。
198→	n, err := h.f.ReadAt(p, h.dataOff+off)
199→	if err != nil && err != io.EOF {
200→		return n, mapError(err)
201→	}
202→	return n, err
203→}
204→
205→func (h *streamHandle) WriteAt(p []byte, off int64) (int, error) {
206→	if err := checkRange(off, len(p)); err != nil {
207→		return 0, err
208→	}
209→	h.mu.Lock()
210→	defer h.mu.Unlock()
211→	if h.closed {
212→		return 0, ErrClosed
213→	}
214→	if !h.writable {
215→		return 0, ErrPermission
216→	}
217→	if h.fs.cfg.ReadOnly {
218→		return 0, ErrReadOnly
219→	}
220→
221→	if h.f == nil {
222→		// AFP_AfpInfo 是**定长**的：写超出 60 字节的部分直接拒绝，
223→		// 而不是悄悄扩容 —— Samba/Apple 的服务器都按定长处理，
224→		// 让缓冲变长会写出一个对端解析不了的 blob。
225→		if off+int64(len(p)) > AfpInfoSize {
226→			return 0, ErrInvalidArg
227→		}
228→		copy(h.buf[off:], p)
229→		h.dirty = true
230→		return len(p), nil
231→	}
232→
233→	n, err := h.f.WriteAt(p, h.dataOff+off)
234→	if err != nil {
235→		return n, mapError(err)
236→	}
237→	if err := h.syncResourceLen(); err != nil {
238→		return n, err
239→	}
240→	return n, nil
241→}
242→
243→// syncResourceLen 把资源段的当前长度回写进 AppleDouble 头。
244→func (h *streamHandle) syncResourceLen() error {
245→	fi, err := h.f.Stat()
246→	if err != nil {
247→		return mapError(err)
248→	}
249→	n := fi.Size() - h.dataOff
250→	if n < 0 {
251→		n = 0
252→	}
253→	return updateResourceForkLen(h.f, h.dataOff, n)
254→}
255→
256→func (h *streamHandle) Truncate(size int64) error {
257→	if size < 0 {
258→		return ErrInvalidArg
259→	}
260→	h.mu.Lock()
261→	defer h.mu.Unlock()
262→	if h.closed {
263→		return ErrClosed
264→	}
265→	if !h.writable {
266→		return ErrPermission
267→	}
268→	if h.fs.cfg.ReadOnly {
269→		return ErrReadOnly
270→	}
271→	return h.truncateLocked(size)
272→}
273→
274→func (h *streamHandle) truncateLocked(size int64) error {
275→	if h.f == nil {
276→		// AFP_AfpInfo 定长，只接受截到 0（等价于清空 FinderInfo）
277→		// 或者截到 60（无操作）。
278→		switch size {
279→		case 0:
280→			h.buf = NewAfpInfo().Marshal()
281→			h.dirty = true
282→			return nil
283→		case AfpInfoSize:
284→			return nil
285→		}
286→		return ErrInvalidArg
287→	}
288→	if err := h.f.Truncate(h.dataOff + size); err != nil {
289→		return mapError(err)
290→	}
291→	return updateResourceForkLen(h.f, h.dataOff, size)
292→}
293→
294→func (h *streamHandle) Sync(full bool) error {
295→	h.mu.Lock()
296→	defer h.mu.Unlock()
297→	if h.closed {
298→		return ErrClosed
299→	}
300→	if err := h.flushLocked(); err != nil {
301→		return err
302→	}
303→	if h.f == nil {
304→		// AFP_AfpInfo 落在 xattr 上，flushLocked 已经写下去了；
305→		// xattr 的持久化跟随基础文件的元数据，没有独立的 fsync 通道。
306→		return nil
307→	}
308→	if full {
309→		return mapError(platformFullSync(h.f))
310→	}
311→	return mapError(h.f.Sync())
312→}
313→
314→// flushLocked 把 AFP_AfpInfo 的内存缓冲回写到 xattr。
315→func (h *streamHandle) flushLocked() error {
316→	if h.f != nil || !h.dirty {
317→		return nil
318→	}
319→	ai, err := ParseAfpInfo(h.buf)
320→	if err != nil {
321→		// 客户端写进来的内容不是合法 AfpInfo。Samba 在这种情况下拒绝写入，
322→		// 但我们已经把数据收下了，只能在落盘时拒绝并保留磁盘上的旧值。
323→		return ErrBadAfpInfo
324→	}
325→	if err := h.fs.writeAfpInfo(h.host, ai); err != nil {
326→		return err
327→	}
328→	h.dirty = false
329→	return nil
330→}
331→
332→// ---------------------------------------------------------------- 属性
333→
334→func (h *streamHandle) Stat() (*Attr, error) {
335→	h.mu.Lock()
336→	defer h.mu.Unlock()
337→	if h.closed {
338→		return nil, ErrClosed
339→	}
340→
341→	// 流的属性基本沿用基础对象（时间戳、属主、DOS 位都取基础对象的），
342→	// 只有 Size/Alloc 换成流自己的长度 —— 这是 Windows 的行为。
343→	a, err := h.fs.statHost(h.host, h.name)
344→	if err != nil {
345→		return nil, err
346→	}
347→	if h.f == nil {
348→		a.Size = AfpInfoSize
349→	} else {
350→		fi, err := h.f.Stat()
351→		if err != nil {
352→			return nil, mapError(err)
353→		}
354→		if n := fi.Size() - h.dataOff; n > 0 {
355→			a.Size = n
356→		} else {
357→			a.Size = 0
358→		}
359→	}
360→	a.Alloc = allocSizeFallback(a.Size)
361→	return a, nil
362→}
363→
364→// SetAttr 在流句柄上是无操作。
365→//
366→// 属性属于基础对象，客户端在流句柄上设属性时 Windows 的行为是接受并
367→// 应用到基础对象；这里选择静默忽略，理由与主数据流的 SetAttr 一致 ——
368→// 报错会让 Finder/Explorer 的复制操作整体失败。
369→func (h *streamHandle) SetAttr(*Attr, AttrMask) error {
370→	h.mu.Lock()
371→	defer h.mu.Unlock()
372→	if h.closed {
373→		return ErrClosed
374→	}
375→	return nil
376→}
377→
378→// ReadDir 在流句柄上永远无效：流不是目录。
379→func (h *streamHandle) ReadDir(string, bool, int) ([]DirEntry, error) {
380→	return nil, ErrNotDir
381→}
382→
383→// Xattr 返回基础对象的扩展属性访问器。
384→func (h *streamHandle) Xattr() (XattrAccessor, error) {
385→	h.mu.Lock()
386→	defer h.mu.Unlock()
387→	if h.closed {
388→		return nil, ErrClosed
389→	}
390→	return newXattrAccessor(h.host, nil)
391→}
392→
393→func (h *streamHandle) Close() error {
394→	h.mu.Lock()
395→	defer h.mu.Unlock()
396→	if h.closed {
397→		return nil
398→	}
399→	h.closed = true
400→
401→	err := h.flushLocked()
402→	if h.f != nil {
403→		if cerr := h.f.Close(); err == nil {
404→			err = mapError(cerr)
405→		}
406→		// 资源段为空的 ._ 文件是垃圾，删掉 —— 留着会在目录里堆积，
407→		// 也会让 macOS 认为每个文件都有资源派生。
408→		h.cleanupEmptyResource()
409→	}
410→	return err
411→}
412→
413→// cleanupEmptyResource 删除资源段为空的 ._ 旁路文件。
414→func (h *streamHandle) cleanupEmptyResource() {
415→	if h.fs.cfg.ReadOnly {
416→		return
417→	}
418→	adPath := dotUnderscoreName(h.host)
419→	if _, ok := resourceForkSize(adPath); ok {
420→		return // 还有内容，留着
421→	}
422→	fi, err := os.Lstat(adPath)
423→	if err != nil || fi.Size() > adRsrcHeaderSize {
424→		// 读不到，或者比一个纯头还大（可能含 FinderInfo 之外的东西），
425→		// 保守起见不删。
426→		return
427→	}
428→	_ = os.Remove(adPath)
429→}
