 14→import (
 15→	"io"
 16→	"os"
 17→	"sync"
 18→)
 19→
 20→// streamHandle 实现 Handle。
 21→type streamHandle struct {
 22→	fs   *LocalFS
 23→	host string // 基础对象的宿主机路径
 24→	name string // 基础对象名（用于 Attr.Name）
 25→	slot string // 规范化后的流名
 26→
 27→	mu     sync.Mutex
 28→	closed bool
 29→
 30→	writable bool
 31→
 32→	// AFP_AfpInfo：内存缓冲 + 脏标记。
 33→	buf   []byte
 34→	dirty bool
 35→
 36→	// AFP_Resource：旁路文件 + 数据段起始偏移。
 37→	f       *os.File
 38→	dataOff int64
 39→}
