 43→// openStream 打开 alternate data stream。
 44→//
 45→// 基础对象必须已存在：SMB 不允许「只创建流不创建文件」，
 46→// 客户端总是先 CREATE 文件本体再 CREATE 它的流。
 47→func (l *LocalFS) openStream(req *OpenRequest, host, name, stream string) (Handle, Action, error) {
 48→	slot := canonicalStreamName(stream)
 49→	if !IsAFPStream(slot) {
 50→		// 通用 ADS 不支持。明确拒绝，不要假装成功（见 stream_store.go 说明）。
 51→		return nil, 0, ErrNotSupported
 52→	}
