 6→// 因此本包对外**绝不能**泄漏裸的 *os.PathError / syscall.Errno。
 7→
 8→import (
 9→	"errors"
10→	"io"
11→	"io/fs"
12→	"syscall"
13→)
14→
15→// mapError 把任意错误映射为 vfs 的 sentinel error。
16→//
17→// 已经是 vfs sentinel 的原样返回；io.EOF 原样返回（Handle.ReadAt 与
18→// Handle.ReadDir 依赖它表达「读完了」）。
19→func mapError(err error) error {
20→	if err == nil {
21→		return nil
22→	}
23→	if errors.Is(err, io.EOF) {
24→		return io.EOF
25→	}
26→	if isVFSError(err) {
27→		return err
28→	}
29→
30→	// errno 优先：fs.ErrPermission 在部分平台会把 EACCES 与 EPERM 混同，
31→	// 而 SMB 需要区分「无权限」与「目录非空」等更细的语义。
32→	var errno syscall.Errno
33→	if errors.As(err, &errno) {
34→		if mapped := mapErrno(errno); mapped != nil {
35→			return mapped
36→		}
37→	}
38→
39→	switch {
40→	case errors.Is(err, fs.ErrNotExist):
41→		return ErrNotFound
42→	case errors.Is(err, fs.ErrExist):
43→		return ErrExist
44→	case errors.Is(err, fs.ErrPermission):
45→		return ErrPermission
46→	case errors.Is(err, fs.ErrClosed):
47→		return ErrClosed
48→	case errors.Is(err, fs.ErrInvalid):
49→		return ErrInvalidPath
50→	}
51→	return err
52→}
53→
54→func isVFSError(err error) bool {
55→	for _, s := range []error{
56→		ErrNotFound, ErrExist, ErrNotDir, ErrIsDir, ErrNotEmpty,
57→		ErrPermission, ErrReadOnly, ErrInvalidPath, ErrNotSupported,
58→		ErrNoSpace, ErrTooLarge, ErrClosed, ErrInvalidArg,
59→	} {
60→		if errors.Is(err, s) {
61→			return true
62→		}
63→	}
64→	return false
65→}
