//
// full=true 对应 SMB2 FLUSH 与 macOS 的 F_FULLFSYNC：
// Time Machine 依赖它保证备份数据真的落到盘片上（AGENTS.md §2 阶段二）。
func (h *localHandle) Sync(full bool) error {
