// 真实的 band 文件名是十六进制序号，这里照抄这个形态 ——
// 名字长度与分布会影响排序与匹配的开销。
func buildBandDir(tb testing.TB, n int) string {
	tb.Helper()
	root := tb.TempDir()
	bands := filepath.Join(root, "bands")
	if err := os.Mkdir(bands, 0o755); err != nil {
		tb.Fatal(err)
	}

