230→func resourceForkSize(adPath string) (int64, bool) {
231→	f, err := os.Open(adPath)
232→	if err != nil {
233→		return 0, false
234→	}
235→	defer func() { _ = f.Close() }()
236→
237→	hdr := make([]byte, adRsrcHeaderSize)
238→	n, err := f.ReadAt(hdr, 0)
239→	if err != nil && n < adHeaderLen {
240→		return 0, false
241→	}
242→	dataOff, dataLen, err := parseRsrcHeader(hdr[:n])
243→	if err != nil {
244→		return 0, false
245→	}
246→	// 头里的长度可能与实际文件大小不一致（被外部工具改过）。
247→	// 以实际大小为准取小值，避免上报一个读不出来的长度。
248→	fi, err := f.Stat()
249→	if err != nil {
250→		return 0, false
251→	}
252→	if actual := fi.Size() - dataOff; actual < dataLen {
253→		if actual < 0 {
254→			actual = 0
255→		}
256→		dataLen = actual
257→	}
258→	if dataLen == 0 {
259→		// 长度为零的资源派生等于没有，不要报告出去 ——
260→		// Finder 看到一个 0 字节的 AFP_Resource 会认为文件损坏。
261→		return 0, false
262→	}
263→	return dataLen, true
264→}
