236→// Resolve 把共享内相对路径解析为宿主机绝对路径。
237→//
238→// 语义：
239→//   - 允许**最后一个分量**不存在（创建场景）；中间分量不存在返回 ErrNotFound。
240→//   - 遇到符号链接（任意一级，含最后一级）会校验其目标仍在根内，
241→//     否则返回 ErrPermission —— 逃逸出共享的软链一律不可访问。
242→//   - 返回的路径**不做**软链替换，仍是 root + 各分量拼接的结果，
243→//     以便调用方对最后一级使用 O_NOFOLLOW / lstat 得到软链自身的属性。
244→func (r *Resolver) Resolve(rel string) (string, error) {
245→	comps, err := SplitPath(rel)
246→	if err != nil {
247→		return "", err
248→	}
249→	return r.resolveComponents(comps)
250→}
251→
252→// ResolveParent 解析出「父目录的宿主机路径」与「最后一个分量的名字」，
253→// 用于 Mkdir / Rename / Remove 这类需要单独处理末级名字的场景。
254→//
255→// 对共享根本身调用返回 ErrInvalidPath（根没有父）。
256→func (r *Resolver) ResolveParent(rel string) (dir string, name string, err error) {
257→	comps, err := SplitPath(rel)
258→	if err != nil {
259→		return "", "", err
260→	}
261→	if len(comps) == 0 {
262→		return "", "", fmt.Errorf("%w: 共享根没有父目录", ErrInvalidPath)
263→	}
264→	dir, err = r.resolveComponents(comps[:len(comps)-1])
265→	if err != nil {
266→		return "", "", err
267→	}
268→	name = comps[len(comps)-1]
269→	if r.caseInsensitive {
270→		if actual, ok := lookupCaseInsensitive(dir, name); ok {
271→			name = actual
272→		}
273→	}
274→	return dir, name, nil
275→}
276→
277→// EvalFinal 把一个**已经过 Resolve 校验**的宿主机路径的最后一跳软链求值成实路径。
278→//
279→// 为什么需要它：Resolve 有意不做软链替换（好让调用方能 lstat 到软链自身），
280→// 但真正 open 的时候我们必须带 O_NOFOLLOW —— 否则「校验通过之后、open 之前」
281→// 这一段时间里最后一级可以被换成指向共享外的软链（TOCTOU）。
282→// 两个需求的调和办法就是：先把软链求值成**实路径**（求值过程中再确认一次
283→// 仍在根内），再对这个不含软链的实路径带 O_NOFOLLOW 打开。
284→// 这样既支持共享内的软链，最后一跳又不可能被偷换。
285→//
286→// 非软链路径原样返回。目标不存在（悬空软链）返回 ErrNotFound。
287→func (r *Resolver) EvalFinal(host string) (string, error) {
288→	fi, err := os.Lstat(host)
289→	if err != nil {
290→		return "", mapError(err)
291→	}
292→	if fi.Mode()&os.ModeSymlink == 0 {
293→		return host, nil
294→	}
295→	real, err := filepath.EvalSymlinks(host)
296→	if err != nil {
297→		return "", mapError(err)
298→	}
299→	if !r.contains(real) {
300→		return "", fmt.Errorf("%w: 符号链接 %q 指向共享外", ErrPermission, host)
301→	}
302→	return real, nil
303→}
304→
305→// resolveComponents 是逐级下降的核心。
306→func (r *Resolver) resolveComponents(comps []string) (string, error) {
307→	cur := r.root
308→	for i, comp := range comps {
309→		last := i == len(comps)-1
310→		next := filepath.Join(cur, comp)
311→
312→		fi, err := os.Lstat(next)
313→		if err != nil && os.IsNotExist(err) && r.caseInsensitive {
314→			if actual, ok := lookupCaseInsensitive(cur, comp); ok {
315→				next = filepath.Join(cur, actual)
316→				fi, err = os.Lstat(next)
317→			}
318→		}
319→		if err != nil {
320→			if !os.IsNotExist(err) {
321→				return "", mapError(err)
322→			}
323→			if last {
324→				// 末级不存在是合法的（FILE_CREATE / FILE_OPEN_IF 等）。
325→				// cur 已确认在根内，comp 不含 ".."，因此 next 必然也在根内。
326→				return next, nil
327→			}
328→			return "", ErrNotFound
329→		}
330→
331→		if fi.Mode()&os.ModeSymlink != 0 {
332→			if err := r.checkSymlink(next); err != nil {
333→				return "", err
334→			}
335→		} else if !last && !fi.IsDir() {
336→			// 中间分量不是目录：POSIX 会给 ENOTDIR，这里提前给出确定的语义。
337→			return "", ErrNotDir
338→		}
339→		cur = next
340→	}
341→	return cur, nil
342→}
343→
344→// checkSymlink 校验一个符号链接（含其后续链条）的最终目标仍在共享根内。
345→func (r *Resolver) checkSymlink(link string) error {
346→	real, err := filepath.EvalSymlinks(link)
347→	if err == nil {
348→		if !r.contains(real) {
349→			return fmt.Errorf("%w: 符号链接 %q 指向共享外", ErrPermission, link)
350→		}
351→		return nil
352→	}
353→	if !os.IsNotExist(err) {
354→		return mapError(err)
355→	}
356→
357→	// 悬空软链（目标暂不存在）：EvalSymlinks 给不出实路径，
358→	// 退化为词法判断 —— 绝对目标一律拒绝，相对目标按父目录拼接后判包含。
359→	// 这样即使目标之后被创建出来，也不可能落在共享外。
360→	target, rerr := os.Readlink(link)
361→	if rerr != nil {
362→		return mapError(rerr)
363→	}
364→	if filepath.IsAbs(target) {
365→		return fmt.Errorf("%w: 符号链接 %q 指向绝对路径 %q", ErrPermission, link, target)
366→	}
367→	joined := filepath.Clean(filepath.Join(filepath.Dir(link), target))
368→	if !r.contains(joined) {
369→		return fmt.Errorf("%w: 符号链接 %q 指向共享外 %q", ErrPermission, link, target)
370→	}
371→	return nil
372→}
373→
374→// contains 判断宿主机路径 p 是否位于共享根之内（含根本身）。
375→func (r *Resolver) contains(p string) bool {
376→	p = filepath.Clean(p)
377→	if p == r.root {
378→		return true
379→	}
380→	return strings.HasPrefix(p, r.root+string(filepath.Separator))
381→}
