// AppleInfoAt 实现 DirAppleMetadata。
func (h *localHandle) AppleInfoAt(name string) ([FinderInfoSize]byte, int64, error) {
	var fi [FinderInfoSize]byte
	if !h.isDir {
		return fi, 0, ErrNotDir
	}
	// 安全边界：name 必须是单个合法分量。ValidateComponent 会拒掉
	// "."、".."、含分隔符与 SMB 非法字符的名字，因此 filepath.Join
	// 不可能拼出目录之外的路径。
	if err := ValidateComponent(name); err != nil {
		return fi, 0, err
	}
	if _, err := h.dirRoot(); err != nil {
		return fi, 0, err
	}
	return h.fs.appleInfoAt(filepath.Join(h.host, name))
}

// dirRoot 做关闭检查，返回目录的宿主机路径。
func (h *localHandle) dirRoot() (string, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return "", ErrClosed
	}
	return h.host, nil
}

// appleInfoAt 是两个入口共用的实现：宿主机路径 → FinderInfo + 资源派生大小。
func (l *LocalFS) appleInfoAt(host string) ([FinderInfoSize]byte, int64, error) {
	var fi [FinderInfoSize]byte
	// 两者都是「没有就算了」：缺 FinderInfo 或缺资源派生都是正常状态。
	if ai, err := l.readAfpInfo(host); err == nil {
		fi = ai.FinderInfo
	}
	rsrc, _ := resourceForkSize(dotUnderscoreName(host))
	return fi, rsrc, nil
}"}

