 49→	// AllocatedRanges 返回 [off, off+length) 内实际已分配（非空洞）的子区间，
 50→	// 对应 FSCTL_QUERY_ALLOCATED_RANGES（MS-FSCC §2.3.20/§2.3.21）。
 51→	//
 52→	// 保证：按 Offset 升序、互不重叠、已裁剪到查询窗口且不越过 EOF。
 53→	// 查询窗口完全落在 EOF 之外，或窗口内全是空洞时，返回 nil, nil ——
 54→	// **空结果是合法答案**，不是错误。
 55→	//
 56→	// 宿主文件系统不支持空洞探测（tmpfs / overlayfs / 部分网络文件系统）
 57→	// 时降级为「整个窗口都已分配」，而不是报错：多报已分配是安全的
 58→	// （客户端最多多读一遍零），少报会让客户端以为数据丢了。
 59→	AllocatedRanges(off, length int64) ([]Range, error)
 60→
 61→	// SetSparse 标记/取消稀疏文件（FSCTL_SET_SPARSE）。
 62→	//
 63→	// POSIX 上文件天然稀疏、没有这个开关，实现为无操作返回 nil ——
 64→	// 返回 ErrNotSupported 会让 macOS 在建 .sparsebundle 时直接放弃。
 65→	SetSparse(v bool) error
 66→}
 67→
 68→// Range 是文件内的一段区间 [Offset, Offset+Length)。
 69→type Range struct {
 70→	Offset int64
 71→	Length int64
 72→}
 73→
 74→// HardLinker 是硬链接能力，对应 SMB2 SET_INFO 的 FileLinkInformation
 75→// （MS-FSCC §2.4.21.2）。
 76→//
 77→// 由 FileSystem 实现（链接是路径级操作，不是句柄级）：
 78→//
 79→//	if hl, ok := fs.(vfs.HardLinker); ok {
 80→//	    err = hl.Link(oldPath, newPath, info.ReplaceIfExists)
 81→//	}
 82→type HardLinker interface {
 83→	// Link 在 newPath 处创建一个指向 oldPath 的硬链接。
 84→	//
 85→	// 两个路径都会过 Resolver 做根目录约束校验（AGENTS.md §8）。
 86→	// replace 对应 ReplaceIfExists：目标已存在时先删再建。
 87→	//
 88→	// 错误：目标已存在且 replace=false → ErrExist；源是目录 → ErrIsDir
 89→	// （POSIX 与 Windows 都不允许目录硬链接）；宿主文件系统不支持硬链接
 90→	// 或跨设备 → ErrNotSupported。
 91→	Link(oldPath, newPath string, replace bool) error
 92→}
 93→
 94→// AppleMetadata 一次性取出 AAPL readdir_attr 需要的 Apple 元数据。
 95→//
 96→// 为什么要有这个：macOS 的 AAPL create context 协商成功后，
 97→// QUERY_DIRECTORY 的每一条目录项都可以顺带携带资源派生大小与 FinderInfo
 98→// （Samba `source3/lib/readdir_attr.h` 的 `struct aapl`）。
 99→// 没有它，Finder 为了拿到同样的信息要对**每个文件**额外开两次流，
100→// 在 Time Machine 的十万级 band 目录上是灾难性的往返次数。
101→//
102→// 由 FileSystem 实现，用类型断言取：
103→//
104→//	if am, ok := fs.(vfs.AppleMetadata); ok {
105→//	    fi, rsrc, err := am.AppleInfo(name)
106→//	}
107→type AppleMetadata interface {
108→	// AppleInfo 返回对象的 32 字节 FinderInfo 与资源派生大小。
109→	//
110→	// 对象存在但没有 Apple 元数据时返回全零 FinderInfo、大小 0 与 nil error
111→	// ——「没有 FinderInfo」是正常状态，不是错误。
112→	//
113→	// 注意 wire 层拼 readdir_attr 时只用得到 FinderInfo 的一个**子集**
114→	// （前 8 字节的类型/创建者码 + 偏移 8 起的标志位，且类型/创建者
115→	// 仅对普通文件填充，目录留零 —— 见 vfs_fruit.c 的
116→	// readdir_attr_meta_finderi）。这里返回完整 32 字节，切片由 wire 决定。
117→	AppleInfo(path string) (finderInfo [FinderInfoSize]byte, rsrcSize int64, err error)
118→}
119→
120→// DirAppleMetadata 是 AppleMetadata 的**目录句柄内**版本，由目录 Handle 实现。
121→//
122→// 为什么要有第二个入口：readdir_attr 是逐条目调用的，而
123→// FileSystem.AppleInfo 每次都要把 "bands/0001a" 这样的路径从共享根
124→// 重新解析一遍（逐级 lstat + 软链校验）。目录句柄已经持有宿主机路径，
125→// 直接拼一个分量即可，在十万级 band 目录上省掉的是十万次重复解析。
126→//
127→//	if dm, ok := dirHandle.(vfs.DirAppleMetadata); ok {
128→//	    fi, rsrc, err := dm.AppleInfoAt(entry.Name)
129→//	}
130→type DirAppleMetadata interface {
131→	// AppleInfoAt 取本目录下**直接子项** name 的 Apple 元数据，
132→	// 语义与 AppleMetadata.AppleInfo 完全一致。
133→	//
134→	// name 必须是单个路径分量：含分隔符、".."、或其他非法字符时返回
135→	// ErrInvalidPath —— 这是安全边界，不能因为「反正是内部调用」就省掉
136→	// （AGENTS.md §8）。
137→	AppleInfoAt(name string) (finderInfo [FinderInfoSize]byte, rsrcSize int64, err error)
138→}
139→
140→var (
141→	_ DeleteOnCloser   = (*localHandle)(nil)
142→	_ SparseFile       = (*localHandle)(nil)
143→	_ AppleMetadata    = (*LocalFS)(nil)
144→	_ DirAppleMetadata = (*localHandle)(nil)
145→	_ HardLinker       = (*LocalFS)(nil)
146→)
147→
148→// AppleInfo 实现 AppleMetadata。
149→func (l *LocalFS) AppleInfo(p string) ([FinderInfoSize]byte, int64, error) {
150→	var fi [FinderInfoSize]byte
151→
152→	base, stream, err := SplitStreamPath(p)
153→	if err != nil {
154→		return fi, 0, err
155→	}
156→	if stream != "" {
157→		// 对一个流查询 Apple 元数据是没有意义的请求。
158→		return fi, 0, ErrInvalidPath
159→	}
160→	host, err := l.res.Resolve(base)
161→	if err != nil {
162→		return fi, 0, err
163→	}
164→	if _, err := os.Lstat(host); err != nil {
165→		return fi, 0, mapError(err)
166→	}
167→
168→	return l.appleInfoAt(host, true)
169→}
170→
171→// AppleInfoAt 实现 DirAppleMetadata。
172→func (h *localHandle) AppleInfoAt(name string) ([FinderInfoSize]byte, int64, error) {
173→	var fi [FinderInfoSize]byte
174→	if !h.isDir {
175→		return fi, 0, ErrNotDir
176→	}
177→	// 安全边界（AGENTS.md §8）：name 必须是单个**真实**分量。
178→	//
179→	// ValidateComponent 会拒掉空串、控制字符、'/'、'\\' 与 Windows 保留
180→	// 设备名，但它**故意放行 "." 与 ".."**（SplitPath 另行处理它们），
181→	// 所以这里必须单独拦一道 —— 否则 filepath.Join(host, "..") 会直接
182→	// 拼出父目录，把 readdir_attr 变成一个目录穿越原语。
183→	if name == "." || name == ".." {
184→		return fi, 0, ErrInvalidPath
185→	}
186→	if err := ValidateComponent(name); err != nil {
187→		return fi, 0, err
188→	}
189→
190→	h.mu.Lock()
191→	if h.closed {
192→		h.mu.Unlock()
193→		return fi, 0, ErrClosed
194→	}
195→	host := h.host
196→	// 已经拍过快照的话，「这个条目有没有 ._ 旁路文件」是已知事实，
197→	// 不必再对每个条目做一次注定 ENOENT 的 open。Time Machine 的 bands
198→	// 目录里一个 ._ 都没有，这一条省掉的是「一次 syscall × 条目数」。
199→	probeRsrc := true
200→	if h.dirNames != nil {
201→		_, probeRsrc = h.dotUnder[name]
202→	}
203→	h.mu.Unlock()
204→
205→	return h.fs.appleInfoAt(filepath.Join(host, name), probeRsrc)
206→}
207→
208→// appleInfoAt 是两个入口共用的实现：宿主机路径 → FinderInfo + 资源派生大小。
209→//
210→// probeRsrc=false 表示调用方已经确知没有 ._ 旁路文件，跳过那次探测。
211→func (l *LocalFS) appleInfoAt(host string, probeRsrc bool) ([FinderInfoSize]byte, int64, error) {
212→	var fi [FinderInfoSize]byte
213→	// 两者都是「没有就算了」：缺 FinderInfo 或缺资源派生都是正常状态。
214→	if ai, err := l.readAfpInfo(host); err == nil {
215→		fi = ai.FinderInfo
216→	}
217→	if !probeRsrc {
218→		return fi, 0, nil
219→	}
220→	rsrc, _ := resourceForkSize(dotUnderscoreName(host))
221→	return fi, rsrc, nil
222→}
223→
224→// SetDeleteOnClose 实现 DeleteOnCloser。
225→func (h *localHandle) SetDeleteOnClose(del bool) error {
226→	if h.fs.cfg.ReadOnly {
227→		return ErrReadOnly
228→	}
229→	h.mu.Lock()
230→	defer h.mu.Unlock()
231→	if h.closed {
232→		return ErrClosed
233→	}
234→	h.deleteOnClose = del
235→	return nil
236→}
237→
238→// PunchHole 实现 SparseFile。
239→func (h *localHandle) PunchHole(off, length int64) error {
240→	if err := checkRange(off, 0); err != nil || length < 0 {
241→		return ErrInvalidArg
242→	}
243→	if length > 0 && off > maxInt64-length {
244→		return ErrInvalidArg
245→	}
246→	if err := h.checkWritable(); err != nil {
247→		return err
248→	}
249→	if length == 0 {
250→		return nil
251→	}
252→	return platformPunchHole(h.f, off, length)
253→}
254→
255→// Preallocate 实现 SparseFile。
256→func (h *localHandle) Preallocate(off, length int64) error {
257→	if off < 0 || length < 0 || (length > 0 && off > maxInt64-length) {
258→		return ErrInvalidArg
259→	}
260→	if err := h.checkWritable(); err != nil {
261→		return err
262→	}
263→	if length == 0 {
264→		return nil
265→	}
266→	return platformPreallocate(h.f, off, length)
267→}
268→
269→// AllocatedRanges 实现 SparseFile。
270→//
271→// 只需要读权限：查询空洞分布不修改文件，Time Machine 在只读挂载上
272→// 也会问（Finder 算「实际占用」）。
273→func (h *localHandle) AllocatedRanges(off, length int64) ([]Range, error) {
274→	if off < 0 || length < 0 || (length > 0 && off > maxInt64-length) {
275→		return nil, ErrInvalidArg
276→	}
277→	if h.isDir {
278→		return nil, ErrIsDir
279→	}
280→	f, err := h.dataFile()
281→	if err != nil {
282→		return nil, err
283→	}
284→	if length == 0 {
285→		return nil, nil
286→	}
287→
288→	// 先夹到 EOF：客户端问的窗口经常直接给 [0, 0x7FFFFFFFFFFFFFFF)，
289→	// 逐个 lseek 到那么远毫无意义，而且返回超出 EOF 的区间会让
290→	// macOS 认为文件比实际更大。
291→	fi, err := f.Stat()
292→	if err != nil {
293→		return nil, mapError(err)
294→	}
295→	end := off + length
296→	if end > fi.Size() {
297→		end = fi.Size()
298→	}
299→	if off >= end {
300→		return nil, nil
301→	}
302→	return platformAllocatedRanges(f, off, end)
303→}
304→
305→// SetSparse 实现 SparseFile。
306→func (h *localHandle) SetSparse(v bool) error {
307→	if err := h.checkWritable(); err != nil {
308→		return err
309→	}
310→	return platformSetSparse(h.f, v)
311→}
312→
313→// dataFile 取出句柄背后的 *os.File，顺带做关闭检查。
314→//
315→// 直接读 h.f 是有竞态的：Close 会在持锁的情况下把它置 nil。
316→func (h *localHandle) dataFile() (*os.File, error) {
317→	h.mu.Lock()
318→	defer h.mu.Unlock()
319→	if h.closed {
320→		return nil, ErrClosed
321→	}
322→	if h.f == nil {
323→		// OpenAttrOnly 句柄没有数据流。
324→		return nil, ErrNotSupported
325→	}
326→	return h.f, nil
327→}
328→
329→// wholeRange 是空洞探测不可用时的保守答案：整个查询窗口都算已分配。
330→func wholeRange(off, end int64) []Range {
331→	if off >= end {
332→		return nil
333→	}
334→	return []Range{{Offset: off, Length: end - off}}
335→}
336→
337→const maxInt64 = int64(^uint64(0) >> 1)
338→

