13→// Link 实现 HardLinker。
14→//
15→// 与 Rename 共用同一套路径处理：两端都走 Resolver.ResolveParent，
16→// 于是 "../"、绝对路径、指向共享外的软链在这里就被挡掉（AGENTS.md §8）。
17→func (l *LocalFS) Link(oldPath, newPath string, replace bool) error {
18→	if l.cfg.ReadOnly {
19→		return ErrReadOnly
20→	}
21→
22→	// 流路径（"file:AFP_Resource:$DATA"）不能作为链接的任何一端：
23→	// 流不是独立的文件系统对象，链接它没有意义。
24→	if _, stream, err := SplitStreamPath(oldPath); err != nil {
25→		return err
26→	} else if stream != "" {
27→		return ErrInvalidPath
28→	}
29→	if _, stream, err := SplitStreamPath(newPath); err != nil {
30→		return err
31→	} else if stream != "" {
32→		return ErrInvalidPath
33→	}
34→
35→	oldDir, oldName, err := l.res.ResolveParent(oldPath)
36→	if err != nil {
37→		return err
38→	}
39→	newDir, newName, err := l.res.ResolveParent(newPath)
40→	if err != nil {
41→		return err
42→	}
43→	src := filepath.Join(oldDir, oldName)
44→	dst := filepath.Join(newDir, newName)
45→
46→	fi, err := os.Lstat(src)
47→	if err != nil {
48→		return mapError(err)
49→	}
50→	if fi.IsDir() {
51→		// POSIX 的 link(2) 对目录返回 EPERM，Windows 的 CreateHardLink
52→		// 返回 ERROR_ACCESS_DENIED —— 两者都会被 mapError 收敛成
53→		// ErrPermission，而客户端真正需要知道的是「这是个目录」。
54→		return ErrIsDir
55→	}
56→
57→	if src == dst {
58→		// 链到自己：Windows 在这里成功返回，不要去删了再建（会丢数据）。
59→		return nil
60→	}
61→
62→	if _, err := os.Lstat(dst); err == nil {
63→		if !replace {
64→			return ErrExist
65→		}
66→		if err := os.Remove(dst); err != nil {
67→			return mapError(err)
68→		}
69→	} else if !os.IsNotExist(err) {
70→		return mapError(err)
71→	}
72→
73→	// 跨设备（bind mount / 子卷挂载点让它在共享内部也可能真实发生）
74→	// 与「本文件系统不支持硬链接」都由 mapErrno 收敛成 ErrNotSupported。
75→	if err := os.Link(src, dst); err != nil {
76→		return mapError(err)
77→	}
78→	// 硬链接是同一个 inode 的新名字，旁路元数据（uid/gid/mode）应当一致。
79→	l.copyMetadata(src, dst)
80→	return nil
81→}
