83→// copyMetadata 把旁路存储里的记录复制到新名字上。
84→// meta 为 nil（Linux/macOS）时是空操作。
85→func (l *LocalFS) copyMetadata(src, dst string) {
86→	if l.meta == nil {
87→		return
88→	}
89→	relSrc, err1 := filepath.Rel(l.res.Root(), src)
90→	relDst, err2 := filepath.Rel(l.res.Root(), dst)
91→	if err1 != nil || err2 != nil {
92→		return
93→	}
94→	if md, ok := l.meta.Get(filepath.ToSlash(relSrc)); ok {
95→		_ = l.meta.Put(filepath.ToSlash(relDst), md)
96→	}
